/**
 * 引用清单只接受 Responses USER input_text，并用搜索时捕获的 Workspace 身份精确匹配；
 * 正文泄漏则扫描整个冻结请求，避免 system、developer 或 instructions 字段绕过验收。
 */
export function composerContextProjection(payload, expectedWorkspaceId) {
  const inputTexts = Array.isArray(payload?.input)
    ? payload.input.flatMap((item) =>
        item?.role === "user" && Array.isArray(item.content)
          ? item.content
              .filter((part) => part?.type === "input_text" && typeof part.text === "string")
              .map((part) => part.text)
          : [],
      )
    : [];
  const payloadStringValues = [];
  JSON.stringify(payload ?? {}, (_key, value) => {
    if (typeof value === "string") payloadStringValues.push(value);
    return value;
  });
  const serializedPayload = payloadStringValues.join("\n");
  const containsManifest = (kind, resourceId) => {
    if (typeof expectedWorkspaceId !== "string" || expectedWorkspaceId.length === 0) return false;
    const expected = `Resource reference [${kind}] ${expectedWorkspaceId}:${resourceId} (content not preloaded).`;
    return inputTexts.some((text) => text.split(/\r?\n/u).includes(expected));
  };

  return {
    skillActivated: serializedPayload.includes(composerContextSkill.bodyMarker),
    fileReferenceProjected: containsManifest("file", "sample.ts"),
    directoryReferenceProjected: containsManifest("directory", "folder-fixture"),
    workspaceBodyAbsent:
      !serializedPayload.includes('export const greeting = "hello from Ja"') &&
      !serializedPayload.includes("visible directory fixture"),
  };
}

