const ordinaryDsmlText = ordinaryDsmlTextFragments.join("");
const businessPrompt =
  "必须先调用 read 工具读取项目根目录 business-context.md，再严格按文件中的“验收输出”回复一行；不要添加解释。";
const frozenExitStageSequence = [
  "exit_requested_enter",
  "exit_requested_return",
  "exit_enter",
  "exit_return",
];
const frozenExitStages = new Set(frozenExitStageSequence);
const snapshotHelpers = new Set();
const sensitiveRedactions = new Set();
let snapshotTail = Promise.resolve();
let visualEvidenceRunDirectory;

/**
 * Windows 下将拒绝访问视为进程仍存活，避免无法检查的 PID 授权删除其他 runner 的锁。
 * 只有 ESRCH 能安全证明锁已过期，其他失败一律保持故障关闭。
 */
function desktopSmokeOwnerIsAlive(pid) {
  if (!Number.isSafeInteger(pid) || pid < 1) return false;
  try {
    process.kill(pid, 0);
    return true;
  } catch (error) {
    return error?.code !== "ESRCH";
  }
}

/** 只读取原子 runner 锁写入的进程身份，避免把锁目录中的其他内容误当成所有权证据。 */
async function readDesktopSmokeLockOwner() {
  try {
    const parsed = JSON.parse(
      await readFile(join(desktopSmokeLockDirectory, "owner.json"), "utf8"),
    );
    return Number.isSafeInteger(parsed?.pid) && typeof parsed?.startedAt === "string"
      ? { pid: parsed.pid, startedAt: parsed.startedAt }
      : undefined;
  } catch {
    return undefined;
  }
}

/**
 * 在分配端口、Cargo 或 HWND 之前串行化整轮 Windows 冒烟测试。
 * 原子目录可跨独立 Codex cell 协调；近期且无 owner 的目录仍视为正在抢占，
 * 只有陈旧或 owner 已退出的锁才会回收，防止并发清理误杀另一轮有效运行。
 */
async function acquireDesktopSmokeLock() {
  for (let attempt = 0; attempt < 2; attempt += 1) {
    try {
      await mkdir(desktopSmokeLockDirectory);
    } catch (error) {
      if (error?.code !== "EEXIST") throw error;
      const owner = await readDesktopSmokeLockOwner();
      const metadata = await stat(desktopSmokeLockDirectory).catch(() => undefined);
      const recentOwnerlessClaim =
        owner === undefined && metadata !== undefined && Date.now() - metadata.mtimeMs < 30_000;
      if (recentOwnerlessClaim || (owner !== undefined && desktopSmokeOwnerIsAlive(owner.pid))) {
        throw new Error(`JA_E2E_RUNNER_BUSY pid=${owner?.pid ?? "claiming"}`);
      }
      if (attempt > 0) throw new Error("JA_E2E_RUNNER_BUSY stale lock could not be reclaimed");
      await rm(desktopSmokeLockDirectory, { recursive: true, force: true });
      continue;
    }
    try {
      await writeFile(
        join(desktopSmokeLockDirectory, "owner.json"),
        JSON.stringify({ pid: process.pid, startedAt: new Date().toISOString() }),
        "utf8",
      );
    } catch (error) {
      await rm(desktopSmokeLockDirectory, { recursive: true, force: true }).catch(() => undefined);
      throw error;
    }
    let released = false;
    return async () => {
      if (released) return;
      released = true;
      const owner = await readDesktopSmokeLockOwner();
      if (owner?.pid === process.pid) {
        await rm(desktopSmokeLockDirectory, { recursive: true, force: true });
      }
    };
  }
  throw new Error("JA_E2E_RUNNER_BUSY");
}

/**
 * 仅在显式启用时捕获产品 viewport 截图。普通验收仍成功后统一发布；preserveOnFailure
 * 只用于显式 UX 审查，使启动失败时已验证的当前画面也能保留在仓库外供诊断。
 */
async function captureVisualEvidence(page, filename, preserveOnFailure = false) {
  if (visualEvidenceDirectory === undefined) {
    return;
  }
  if (visualEvidenceRunDirectory === undefined) {
    throw new Error("视觉证据 staging 尚未初始化");
  }
  await mkdir(visualEvidenceRunDirectory, { recursive: true });
  const stagedPath = join(visualEvidenceRunDirectory, filename);
  await page.screenshot({ path: stagedPath, fullPage: false });
  if (preserveOnFailure) {
    await mkdir(visualEvidenceDirectory, { recursive: true });
    await copyFile(stagedPath, join(visualEvidenceDirectory, filename));
  }
}

/** 首进程与重启共用可见性、顺序和截图断言；持久化 rows 不能证明 Timeline 已真实渲染。 */
async function verifyAndCaptureComposerContextTimeline(
  page,
  orderedMessages,
  deadline,
  phase,
  directories,
) {
  const timeline = page.getByRole("region", { name: "对话时间线", exact: true });
  const missingMessages = [];
  for (const message of orderedMessages) {
    try {
      await message.locator.waitFor({
        state: "visible",
        timeout: Math.max(1, deadline - Date.now()),
      });
    } catch {
      missingMessages.push(message.label);
    }
  }
  if (missingMessages.length > 0) {
    throw new Error(`${phase} 后 Timeline 消息缺失：${missingMessages.join(", ")}`);
  }

  const timelineText = await timeline.innerText();
  const messagePositions = orderedMessages.map(({ text }) => timelineText.indexOf(text));
  if (
    messagePositions.some((position) => position < 0) ||
    messagePositions.some((position, index) => index > 0 && position <= messagePositions[index - 1])
  ) {
    throw new Error(`${phase} 后 Timeline 消息顺序错误：${JSON.stringify(messagePositions)}`);
  }

  if (visualEvidenceDirectory === undefined) {
    return {
      timelineMessagesVisibleAndOrdered: true,
      timelineVisualEvidence: { status: "skipped" },
    };
  }

  const filename = `composer-context-timeline-${phase}.png`;
  await captureVisualEvidence(page, filename, true);
  const screenshotPath = join(visualEvidenceDirectory, filename);
  const manifestPath = `${screenshotPath}.manifest.json`;
  const sourcePaths = [
    "apps/desktop/src/features/conversation/ui/timeline/ChatTimeline.tsx",
    "apps/desktop/tests/features/conversation/ui/ChatTimeline.test.tsx",
  ];
  const [screenshot, pageTitle, viewport, runnerSource, ...sourceContents] = await Promise.all([
    readFile(screenshotPath),
    page.title(),
    page.evaluate(() => ({
      width: globalThis.innerWidth,
      height: globalThis.innerHeight,
      devicePixelRatio: globalThis.devicePixelRatio,
    })),
    readFile(fileURLToPath(import.meta.url)),
    ...sourcePaths.map((path) => readFile(join(repoRoot, path))),
  ]);
  if (
    !Number.isSafeInteger(viewport.width) ||
    viewport.width <= 0 ||
    !Number.isSafeInteger(viewport.height) ||
    viewport.height <= 0 ||
    !Number.isFinite(viewport.devicePixelRatio) ||
    viewport.devicePixelRatio <= 0
  ) {
    throw new Error(`${phase} Timeline screenshot viewport 无效`);
  }
  const manifest = {
    status: "captured",
    scenarioId: "composer_context",
    phase,
    capturedAt: new Date().toISOString(),
    surface: "isolated_webview2_renderer_viewport",
    captureMethod: "Playwright Page.screenshot over the attached app CDP page",
    fullPage: false,
    messageOrder: ["user", "assistant", "user", "assistant"],
    screenshotFile: filename,
    screenshotBytes: screenshot.byteLength,
    screenshotSha256: createHash("sha256").update(screenshot).digest("hex"),
    pageUrl: redact(page.url(), directories),
    pageTitle: redact(pageTitle, directories),
    viewport,
    runnerPath: "scripts/e2e/windows-desktop-smoke.mjs",
    runnerSha256: createHash("sha256").update(runnerSource).digest("hex"),
    sourceFiles: sourcePaths.map((path, index) => ({
      path,
      sha256: createHash("sha256").update(sourceContents[index]).digest("hex"),
    })),
  };
  await writeFile(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`, "utf8");
  return {
    timelineMessagesVisibleAndOrdered: true,
    timelineVisualEvidence: {
      status: manifest.status,
      screenshotFile: filename,
      manifestFile: `${filename}.manifest.json`,
      screenshotSha256: manifest.screenshotSha256,
      runnerSha256: manifest.runnerSha256,
      viewport,
      sourceFiles: manifest.sourceFiles,
    },
  };
}

