/**
 * 在原错误处理仍持有隔离 WebView 页面时保存 viewport 与来源 manifest；同时记录可直接打开的绝对产物路径，
 * 避免汇总报告只留 basename 后无法从 runner 启动参数还原证据目录。元数据读取受整轮取消
 * 和短 deadline 约束，截图失败只记入证据，不覆盖原始错误或截取宿主桌面。
 * Thread identity 与 Host 隔离属性只辅助区分保活和 Portal 遮蔽，不替代原生资源回收证据。
 * @author kongweiguang
 */
export async function captureFailureVisualEvidence(
  page,
  runId,
  phase,
  error,
  directories,
  {
    signal,
    outputDirectory = visualEvidenceDirectory,
    metadataTimeoutMs = failureVisualMetadataTimeoutMs,
  } = {},
) {
  if (outputDirectory === undefined) {
    return { status: "skipped", reason: "screenshot_directory_not_configured" };
  }
  const filename = `${runId}-${phase}-failure.png`;
  const screenshotPath = resolve(outputDirectory, filename);
  const manifestPath = `${screenshotPath}.manifest.json`;
  const manifest = {
    status: "capture_failed",
    runId,
    phase,
    capturedAt: new Date().toISOString(),
    surface: "isolated_webview2_renderer_viewport",
    captureMethod: "Playwright Page.screenshot over the attached app CDP page",
    fullPage: false,
    screenshotFile: filename,
    screenshotPath,
    manifestPath,
    originalFailure: redact(error instanceof Error ? error.message : String(error), directories),
  };
  try {
    await mkdir(outputDirectory, { recursive: true });
    const screenshot = await page.screenshot({ fullPage: false, timeout: 5_000 });
    await writeFile(screenshotPath, screenshot);
    Object.assign(manifest, {
      status: "captured",
      screenshotBytes: screenshot.byteLength,
      screenshotSha256: createHash("sha256").update(screenshot).digest("hex"),
    });
    const metadataDeadline = createDeadline("failure visual metadata", metadataTimeoutMs);
    try {
      const metadataSignal = combineSignals([signal, metadataDeadline.signal]);
      const [pageTitle, pageMetadata, runnerSource] = await raceWithSignal(
        () =>
          Promise.all([
            page.title(),
            page.evaluate(() => {
              const hosts = [
                ...globalThis.document.querySelectorAll("[data-thread-workbench-scope]"),
              ];
              return {
                viewport: {
                  width: globalThis.innerWidth,
                  height: globalThis.innerHeight,
                  devicePixelRatio: globalThis.devicePixelRatio,
                },
                threadWorkbench: {
                  selectedThreadId:
                    globalThis.document
                      .querySelector('[aria-label="最近对话列表"] button[aria-current="page"]')
                      ?.getAttribute("data-thread-id") ?? null,
                  hostCount: hosts.length,
                  truncated: hosts.length > 32,
                  hosts: hosts.slice(0, 32).map((host) => ({
                    scope: host.getAttribute("data-thread-workbench-scope"),
                    hidden: host.hasAttribute("hidden"),
                    inert: host.hasAttribute("inert"),
                    ariaHidden: host.getAttribute("aria-hidden"),
                    inlineDisplay: host.style.display,
                    inspectorVisible:
                      host.querySelector(".ja-inspector")?.getAttribute("data-visible") ?? null,
                  })),
                },
              };
            }),
            readFile(fileURLToPath(import.meta.url)),
          ]),
        metadataSignal,
      );
      Object.assign(manifest, {
        pageUrl: redact(page.url(), directories),
        pageTitle: redact(pageTitle, directories),
        viewport: pageMetadata.viewport,
        threadWorkbench: pageMetadata.threadWorkbench,
        runnerPath: "scripts/e2e/windows-desktop-smoke.mjs",
        runnerSha256: createHash("sha256").update(runnerSource).digest("hex"),
      });
    } catch (metadataError) {
      manifest.metadataError = redact(
        metadataError instanceof Error ? metadataError.message : String(metadataError),
        directories,
      );
    } finally {
      metadataDeadline.cancel();
    }
  } catch (captureError) {
    Object.assign(manifest, {
      captureError: redact(
        captureError instanceof Error ? captureError.message : String(captureError),
        directories,
      ),
    });
  }
  try {
    await writeFile(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`, "utf8");
  } catch (manifestError) {
    return {
      ...manifest,
      manifestError: redact(
        manifestError instanceof Error ? manifestError.message : String(manifestError),
        directories,
      ),
    };
  }
  return manifest;
}

/**
 * 从真实 WebView2 读取分隔器状态与光带伪元素；同时采集 hover/focus/drag 和透明度，
 * 以区分 pointer 离开时保留坐标的淡出与键盘焦点时恢复中心位置。
 */
async function readResizeHandleVisual(separator) {
  return separator.evaluate((element) => {
    const style = globalThis.getComputedStyle(element);
    const spotlight = globalThis.getComputedStyle(element, "::after");
    return {
      sharedClass: element.classList.contains("ja-resize-handle"),
      pointerY: element.style.getPropertyValue("--ja-resize-pointer-y").trim(),
      accent: style.getPropertyValue("--ja-accent").trim(),
      focus: style.getPropertyValue("--ja-focus").trim(),
      backgroundImage: spotlight.backgroundImage,
      backgroundColor: spotlight.backgroundColor,
      opacity: Number.parseFloat(spotlight.opacity),
      hovered: element.matches(":hover"),
      focused: globalThis.document.activeElement === element,
      dragging: element.hasAttribute("data-dragging"),
    };
  });
}

/**
 * 普通 smoke 只在完整成功后从 staging 发布；Plan focused driver 已直接写入其隔离证据目录，
 * 此处只枚举而不自复制，二者都必须返回真实文件才能通过最终非空门。
 */
async function publishVisualEvidenceRun() {
  if (visualEvidenceDirectory === undefined || visualEvidenceRunDirectory === undefined) return [];
  await mkdir(visualEvidenceDirectory, { recursive: true });
  const sourceDirectory = visualEvidenceRunDirectory;
  const entries = await readdir(sourceDirectory, { withFileTypes: true });
  const published = [];
  for (const entry of entries) {
    if (!entry.isFile()) continue;
    if (sourceDirectory !== visualEvidenceDirectory) {
      await copyFile(join(sourceDirectory, entry.name), join(visualEvidenceDirectory, entry.name));
    }
    published.push(entry.name);
  }
  return published.sort();
}

/**
 * 捕获 renderer 模拟的 CSS viewport。文件名和返回值刻意标明 renderer，
 * 防止这份证据被误报为 Windows 原生窗口尺寸或最大化断言。
 */
async function captureRendererVisualEvidenceAtViewport(page, filename, viewport) {
  if (visualEvidenceDirectory === undefined) {
    return {
      status: "skipped",
      surface: "renderer_emulation",
      reason: "screenshot_directory_not_configured",
    };
  }
  const client = await page.context().newCDPSession(page);
  try {
    await client.send("Emulation.setDeviceMetricsOverride", {
      ...viewport,
      deviceScaleFactor: 1,
      mobile: false,
    });
    await page.waitForTimeout(180);
    await captureVisualEvidence(page, filename);
    const metrics = await page.evaluate(() => ({
      innerWidth: globalThis.innerWidth,
      innerHeight: globalThis.innerHeight,
      devicePixelRatio: globalThis.devicePixelRatio,
    }));
    return { status: "captured", surface: "renderer_emulation", nativeWindow: false, ...metrics };
  } finally {
    await client.send("Emulation.clearDeviceMetricsOverride").catch(() => undefined);
    await client.detach().catch(() => undefined);
  }
}

/** 对照原生 PhysicalSize/缩放和 renderer CSS 几何，拒绝未最大化或仍处于 CDP 仿真的截图。 */
export function assertNativeViewportGeometry(metrics, nativeWindow, requiredPixelRatio = null) {
  const scale = nativeWindow?.scaleFactor;
  const width = nativeWindow?.innerSize?.width;
  const height = nativeWindow?.innerSize?.height;
  if (
    nativeWindow?.maximized !== true ||
    metrics?.maximized !== true ||
    !Number.isFinite(scale) ||
    scale <= 0 ||
    !Number.isSafeInteger(width) ||
    width <= 0 ||
    !Number.isSafeInteger(height) ||
    height <= 0 ||
    !Number.isFinite(metrics.innerWidth) ||
    metrics.innerWidth <= 0 ||
    !Number.isFinite(metrics.innerHeight) ||
    metrics.innerHeight <= 0 ||
    !Number.isFinite(metrics.devicePixelRatio) ||
    metrics.devicePixelRatio <= 0 ||
    Math.abs(metrics.devicePixelRatio - scale) > 0.01 ||
    Math.abs(metrics.innerWidth - width / scale) > 1 ||
    Math.abs(metrics.innerHeight - height / scale) > 1 ||
    (requiredPixelRatio !== null &&
      (!Number.isFinite(requiredPixelRatio) ||
        requiredPixelRatio <= 0 ||
        Math.abs(scale - requiredPixelRatio) > 0.01))
  ) {
    throw new Error("native window and renderer geometry disagree");
  }
  return { width: metrics.innerWidth, height: metrics.innerHeight, devicePixelRatio: scale };
}

/**
 * 最大化结论必须由动作前后的同一 owned HWND、Win32 状态、Tauri 几何和 renderer 投影共同证明；
 * ShowWindowAsync 的布尔值只记录异步请求是否被接受，不能被当作最大化完成证明。
 */
export function assertMaximizedWindowEvidence(evidence, expectedPid) {
  const native = evidence?.native;
  const identityIsExact = (identity) =>
    identity?.valid === true &&
    identity.pid === expectedPid &&
    identity.pidMatches === true &&
    identity.nameMatches === true &&
    identity.commandLineMatches === true &&
    identity.creationDateMatches === true;
  const rectangleIsValid = (rectangle) =>
    rectangle !== null &&
    typeof rectangle === "object" &&
    [rectangle.left, rectangle.top, rectangle.right, rectangle.bottom].every(Number.isFinite) &&
    Number.isFinite(rectangle.width) &&
    rectangle.width > 0 &&
    Number.isFinite(rectangle.height) &&
    rectangle.height > 0;
  const windowIsOwned = (window) =>
    Number.isSafeInteger(window?.hwnd) &&
    window.hwnd > 0 &&
    window.processId === expectedPid &&
    window.isWindow === true &&
    window.visible === true &&
    window.title === nativeJaWindowTitle &&
    typeof window.iconic === "boolean" &&
    typeof window.zoomed === "boolean" &&
    rectangleIsValid(window.windowRect) &&
    rectangleIsValid(window.clientRect);
  const before = native?.before;
  const after = native?.after;
  const renderer = evidence?.renderer;
  const tauri = evidence?.tauri;
  const invalid =
    native?.action !== "maximize" ||
    native.pid !== expectedPid ||
    !identityIsExact(native.identityBefore) ||
    !identityIsExact(native.identityAfter) ||
    typeof native.showWindowAsyncRequestAccepted !== "boolean" ||
    native.showWindowAsyncReturnSemantics !== "request_accepted" ||
    !windowIsOwned(before) ||
    !windowIsOwned(after) ||
    before.hwnd !== after.hwnd ||
    native.boundWindowHandleBefore !== before.hwnd ||
    native.boundWindowHandleAfter !== after.hwnd ||
    after.iconic ||
    !after.zoomed ||
    renderer?.maximized !== true ||
    !Number.isFinite(renderer.outerWidth) ||
    renderer.outerWidth <= 0 ||
    !Number.isFinite(renderer.outerHeight) ||
    renderer.outerHeight <= 0;
  if (invalid) {
    throw new Error(`owned native maximize evidence invalid: ${JSON.stringify(evidence)}`);
  }
  return assertNativeViewportGeometry(renderer, tauri);
}

/**
 * 把诊断附到同一个 Error 对象，确保 phase summary 能保留证据且原异常栈不被包装或改写。
 */
export function attachMaximizedWindowEvidence(error, evidence) {
  if (!(error instanceof Error)) return error;
  Object.defineProperty(error, "windowMaximizeEvidence", {
    configurable: true,
    value: evidence,
  });
  return error;
}

/** 通过真实标题栏最大化，并读取当前 Tauri 窗口权威几何；每轮实际显示器尺寸进入证据。 */
async function assertNativeMaximizedVisualViewport(page, deadline) {
  if (visualEvidenceDirectory === undefined) {
    return {
      status: "skipped",
      surface: "native_window",
      reason: "screenshot_directory_not_configured",
    };
  }
  const timeout = () => Math.max(1, deadline - Date.now());
  const restore = page.getByRole("button", { name: "还原", exact: true });
  if ((await restore.count()) === 0) {
    const maximize = page.getByRole("button", { name: "最大化", exact: true });
    await maximize.waitFor({ state: "visible", timeout: timeout() });
    await clickVerifiedControl(page, maximize, deadline);
  }
  await restore.waitFor({ state: "visible", timeout: timeout() });
  await page
    .locator('.ja-titlebar[data-window-maximized="true"]')
    .waitFor({ state: "visible", timeout: timeout() });
  const nativeWindow = await page.evaluate(async () => {
    // evaluate 不经 Vite 转换；直接使用已安装 Tauri API 同名 commands，避免浏览器解析 bare import。
    const native = globalThis.__TAURI_INTERNALS__;
    const invoke = native?.invoke;
    const label = native?.metadata?.currentWindow?.label;
    if (typeof invoke !== "function" || typeof label !== "string" || label.length === 0)
      throw new Error("native window bridge unavailable");
    const [maximized, size, scaleFactor] = await Promise.all([
      invoke("plugin:window|is_maximized", { label }),
      invoke("plugin:window|inner_size", { label }),
      invoke("plugin:window|scale_factor", { label }),
    ]);
    return { maximized, innerSize: { width: size.width, height: size.height }, scaleFactor };
  });
  await page.waitForFunction(
    (native) =>
      Math.abs(globalThis.innerWidth - native.innerSize.width / native.scaleFactor) <= 1 &&
      Math.abs(globalThis.innerHeight - native.innerSize.height / native.scaleFactor) <= 1 &&
      Math.abs(globalThis.devicePixelRatio - native.scaleFactor) <= 0.01,
    nativeWindow,
    { timeout: timeout() },
  );
  const metrics = await page.evaluate(() => ({
    innerWidth: globalThis.innerWidth,
    innerHeight: globalThis.innerHeight,
    outerWidth: globalThis.outerWidth,
    outerHeight: globalThis.outerHeight,
    devicePixelRatio: globalThis.devicePixelRatio,
    screenWidth: globalThis.screen.width,
    screenHeight: globalThis.screen.height,
    availableWidth: globalThis.screen.availWidth,
    availableHeight: globalThis.screen.availHeight,
    maximized:
      globalThis.document.querySelector(".ja-titlebar")?.getAttribute("data-window-maximized") ===
      "true",
  }));
  const expected = assertNativeViewportGeometry(
    metrics,
    nativeWindow,
    configuredNativeDevicePixelRatio,
  );
  Object.assign(nativeVisualViewport, expected);
  return {
    status: "passed",
    surface: "native_window",
    expected,
    nativeWindow,
    ...metrics,
  };
}

/** 截图须维持刚核验的当前原生 viewport，避免 CDP 尺寸覆盖被误报为系统窗口证据。 */
async function captureNativeMaximizedVisualEvidence(page, filename, nativeViewportEvidence) {
  if (visualEvidenceDirectory === undefined) return;
  if (
    nativeViewportEvidence?.status !== "passed" ||
    nativeViewportEvidence.surface !== "native_window"
  ) {
    throw new Error("缺少当前 native 最大化断言，拒绝生成 native 视觉证据");
  }
  const metrics = await page.evaluate(() => ({
    width: globalThis.innerWidth,
    height: globalThis.innerHeight,
    devicePixelRatio: globalThis.devicePixelRatio,
  }));
  if (
    metrics.width !== nativeViewportEvidence.expected.width ||
    metrics.height !== nativeViewportEvidence.expected.height ||
    Math.abs(metrics.devicePixelRatio - nativeViewportEvidence.expected.devicePixelRatio) > 0.01
  ) {
    throw new Error(`native 截图前视口发生变化：${JSON.stringify(metrics)}`);
  }
  await captureVisualEvidence(page, filename);
}

/**
 * 在真实 WebView2 renderer 中覆盖设置中心的生产窗口、800/799 相邻断点与辅助状态；
 * 每帧都检查可见祖先树及专属分类导航。会话工作区为保留 owner 而隐藏挂载，DOM 存在本身
 * 不能证明画面可见；Conversation 与 Workbench 仍必须完全退出可见区域。强制颜色焦点检查
 * 使用真实 Tab 导航，避免程序化 focus 被误当成键盘焦点可见性。
 */
async function captureResponsiveVisualEvidence(page) {
  if (visualEvidenceDirectory === undefined) {
    return [];
  }
  const client = await page.context().newCDPSession(page);
  const evidence = [];
  /** 同时记录 viewport 真值与 overflow，使截图无法掩盖布局裁切。 */
  const record = async (label, expectedMedia = {}) => {
    await page.waitForTimeout(180);
    const metrics = await page.evaluate(() => {
      /** 检查节点及所有祖先的隐藏状态，覆盖 workspace 子树被 hidden/aria-hidden 保留挂载。 */
      const isVisible = (element) => {
        if (element === null) return false;
        for (let ancestor = element; ancestor !== null; ancestor = ancestor.parentElement) {
          const style = globalThis.getComputedStyle(ancestor);
          if (
            ancestor.hidden ||
            ancestor.getAttribute("aria-hidden") === "true" ||
            style.display === "none" ||
            style.visibility === "hidden" ||
            style.visibility === "collapse" ||
            Number(style.opacity) === 0
          ) {
            return false;
          }
        }
        const bounds = element.getBoundingClientRect();
        return bounds.width > 0 && bounds.height > 0;
      };
      const settingsLayout = globalThis.document.querySelector(".ja-layout.is-settings");
      const settingsPage = settingsLayout?.querySelector('[aria-label="设置页面"]') ?? null;
      const settingsNavigation =
        settingsPage?.querySelector('.ja-settings-nav[role="tablist"]') ?? null;
      const tabs = [...(settingsNavigation?.querySelectorAll('[role="tab"]') ?? [])]
        .map((tab) => tab.textContent?.trim() ?? "")
        .filter(Boolean);
      const returnButton = globalThis.document.querySelector(".ja-settings-return");
      const search = globalThis.document.querySelector(".ja-settings-search");
      const returnRect = returnButton?.getBoundingClientRect();
      const searchRect = search?.getBoundingClientRect();
      return {
        innerWidth: globalThis.innerWidth,
        innerHeight: globalThis.innerHeight,
        devicePixelRatio: globalThis.devicePixelRatio,
        scrollWidth: globalThis.document.documentElement.scrollWidth,
        scrollHeight: globalThis.document.documentElement.scrollHeight,
        forcedColors: globalThis.matchMedia("(forced-colors: active)").matches,
        reducedMotion: globalThis.matchMedia("(prefers-reduced-motion: reduce)").matches,
        settingsShell:
          isVisible(settingsLayout) && isVisible(settingsPage) && isVisible(settingsNavigation),
        conversationCount: [...globalThis.document.querySelectorAll(".ja-conversation")].filter(
          isVisible,
        ).length,
        navigationCount: globalThis.document.querySelectorAll(".ja-navigation-sidebar").length,
        workbenchCount: [...globalThis.document.querySelectorAll(".ja-workbench")].filter(isVisible)
          .length,
        returnCount: globalThis.document.querySelectorAll(".ja-settings-return").length,
        legacyScopeCount: globalThis.document.querySelectorAll(".ja-settings-scope").length,
        legacyStartCount: globalThis.document.querySelectorAll(".ja-settings-start").length,
        legacyHeadingCount: globalThis.document.querySelectorAll(".ja-settings-sidebar-heading")
          .length,
        returnSearchGeometry:
          returnRect === undefined || searchRect === undefined
            ? null
            : {
                leftDelta: Math.abs(returnRect.left - searchRect.left),
                widthDelta: Math.abs(returnRect.width - searchRect.width),
              },
        returnFocused: globalThis.document.activeElement === returnButton,
        returnOutline: returnButton?.matches(":focus-visible")
          ? globalThis.getComputedStyle(returnButton).outlineStyle
          : "none",
        tabs,
      };
    });
    if (metrics.scrollWidth > metrics.innerWidth + 1) {
      throw new Error(`${label} 出现水平溢出 ${metrics.scrollWidth}/${metrics.innerWidth}`);
    }
    if (
      !metrics.settingsShell ||
      metrics.conversationCount !== 0 ||
      metrics.navigationCount !== 0 ||
      metrics.workbenchCount !== 0 ||
      metrics.returnCount !== 1 ||
      metrics.legacyScopeCount !== 0 ||
      metrics.legacyStartCount !== 0 ||
      metrics.legacyHeadingCount !== 0 ||
      metrics.returnSearchGeometry === null ||
      metrics.returnSearchGeometry.leftDelta > 1 ||
      metrics.returnSearchGeometry.widthDelta > 1 ||
      JSON.stringify(metrics.tabs) !==
        JSON.stringify([
          "通用",
          "外观",
          "模型",
          "子智能体",
          "执行确认",
          "Skills",
          "MCP",
          "数据与存储",
          "关于",
        ])
    ) {
      throw new Error(`${label} 设置专属 Shell 不完整：${JSON.stringify(metrics)}`);
    }
    if (
      (expectedMedia.forcedColors !== undefined &&
        metrics.forcedColors !== expectedMedia.forcedColors) ||
      (expectedMedia.reducedMotion !== undefined &&
        metrics.reducedMotion !== expectedMedia.reducedMotion)
    ) {
      throw new Error(`${label} 媒体能力模拟未生效：${JSON.stringify(metrics)}`);
    }
    if (
      expectedMedia.forcedColors === true &&
      (!metrics.returnFocused || metrics.returnOutline === "none")
    ) {
      throw new Error(`${label} 返回应用焦点在高对比度下不可见：${JSON.stringify(metrics)}`);
    }
    await captureVisualEvidence(
      page,
      `implementation-settings-center-${visualTheme}-renderer-${label}.png`,
    );
    evidence.push({ label, surface: "renderer_emulation", nativeWindow: false, ...metrics });
  };
  try {
    for (const viewport of [
      { width: 1280, height: 820 },
      { width: 980, height: 720 },
      { width: 800, height: 640 },
      { width: 799, height: 640 },
      { width: 720, height: 640 },
    ]) {
      await client.send("Emulation.setDeviceMetricsOverride", {
        ...viewport,
        deviceScaleFactor: 1,
        mobile: false,
      });
      await record(`${viewport.width}x${viewport.height}`);
    }
    await client.send("Emulation.setDeviceMetricsOverride", {
      width: 720,
      height: 640,
      deviceScaleFactor: 2,
      mobile: false,
    });
    await record("dpr2-720x640");
    await client.send("Emulation.setDeviceMetricsOverride", {
      width: 1280,
      height: 820,
      deviceScaleFactor: 1,
      mobile: false,
    });
    await page.emulateMedia({ forcedColors: "active", reducedMotion: "reduce" });
    const returnButton = page.getByRole("button", { name: "返回应用", exact: true });
    const traversal = await page.evaluate(() => {
      const target = globalThis.document.querySelector(".ja-settings-return");
      const active = globalThis.document.activeElement;
      const tabStopCount = [
        ...globalThis.document.querySelectorAll(
          "a[href], button, input, select, textarea, [tabindex]",
        ),
      ].filter((element) => {
        const style = globalThis.getComputedStyle(element);
        return (
          element.tabIndex >= 0 &&
          !element.matches(":disabled") &&
          style.display !== "none" &&
          style.visibility !== "hidden" &&
          style.visibility !== "collapse" &&
          element.getClientRects().length > 0
        );
      }).length;
      const targetFollowsActive =
        target !== null &&
        active !== null &&
        (active.compareDocumentPosition(target) & globalThis.Node.DOCUMENT_POSITION_FOLLOWING) !==
          0;
      return { tabStopCount, key: targetFollowsActive ? "Tab" : "Shift+Tab" };
    });
    let focusedByKeyboard = false;
    for (let step = 0; step < traversal.tabStopCount; step += 1) {
      await page.keyboard.press(traversal.key);
      if (await returnButton.evaluate((element) => globalThis.document.activeElement === element)) {
        focusedByKeyboard = true;
        break;
      }
    }
    if (!focusedByKeyboard) {
      throw new Error("真实 Tab 导航未到达设置页返回应用按钮");
    }
    await record("forced-colors-reduced-motion-1280x820", {
      forcedColors: true,
      reducedMotion: true,
    });
  } finally {
    await page
      .emulateMedia({ forcedColors: "none", reducedMotion: "no-preference" })
      .catch(() => undefined);
    await client.send("Emulation.clearDeviceMetricsOverride").catch(() => undefined);
    // Direct CDP 连接与 WebView2 target 共用生命周期；显式 detach 在 Windows 151
    // 会销毁唯一 renderer，统一交给阶段末尾 browser.close() 释放 transport。
  }
  return evidence;
}

/**
 * 以产品的可访问语义定位唯一对话根面，避免 E2E 依赖已经删除的测试专用 DOM 标记；
 * 后续项目范围、设置返回和重启恢复均共享同一稳定边界。
 */
function conversationSurface(page) {
  return page.getByRole("region", { name: "coding 对话", exact: true });
}

/**
 * 通过设置页的真实 Radix 控件切换本轮视觉主题和产品级辅助偏好。
 * 先提交 WebView 本地辅助偏好、最后单独等待主题 CAS 收敛，避免主题保存期间的 Query 重读
 * 与后续本地状态提交交错；主题必须落到 document authority，辅助偏好必须进入语义 data attribute；
 * 聚焦业务验收可跳过设置页截图矩阵，避免用无关路由门禁掩盖目标状态机证据。
 */
async function applyVisualPreferences(page, deadline, { captureSettingsEvidence = true } = {}) {
  const timeout = () => Math.max(1, deadline - Date.now());
  await page.getByRole("button", { name: "设置", exact: true }).click();
  const settings = page.getByRole("region", { name: "设置页面", exact: true });
  await settings.waitFor({ state: "visible", timeout: timeout() });
  await settings.getByRole("tab", { name: "外观", exact: true }).click();
  for (const [name, attribute] of [
    ["减少动效", "data-reduce-motion"],
    ["降低透明度", "data-reduced-transparency"],
    ["提高对比度", "data-high-contrast"],
  ]) {
    const toggle = settings.getByRole("switch", { name, exact: true });
    // 每项设置都经过独立 CAS 保存；等待上一项解除 disabled 后再继续，避免并发点击伪造失败。
    await page.waitForFunction(
      (accessibleName) => {
        const candidate = [...globalThis.document.querySelectorAll('[role="switch"]')].find(
          (element) => element.getAttribute("aria-label") === accessibleName,
        );
        return (
          candidate !== undefined &&
          !candidate.hasAttribute("disabled") &&
          candidate.getAttribute("aria-disabled") !== "true"
        );
      },
      name,
      { timeout: timeout() },
    );
    if ((await toggle.getAttribute("aria-checked")) !== "true") await toggle.click();
    await page.waitForFunction(
      ({ accessibleName, rootAttribute }) => {
        const candidate = [...globalThis.document.querySelectorAll('[role="switch"]')].find(
          (element) => element.getAttribute("aria-label") === accessibleName,
        );
        return (
          candidate?.getAttribute("aria-checked") === "true" &&
          !candidate.hasAttribute("disabled") &&
          candidate.getAttribute("aria-disabled") !== "true" &&
          globalThis.document.documentElement.getAttribute(rootAttribute) === "true"
        );
      },
      { accessibleName: name, rootAttribute: attribute },
      { timeout: timeout() },
    );
  }
  const theme = settings.getByRole("combobox", { name: "外观模式", exact: true });
  await theme.click();
  await page
    .getByRole("option", { name: visualTheme === "light" ? "浅色" : "深色", exact: true })
    .click();
  await page.waitForFunction(
    (expectedTheme) => {
      const root = globalThis.document.documentElement;
      return (
        root.getAttribute("data-theme") === expectedTheme &&
        root.getAttribute("data-theme-mode") === expectedTheme
      );
    },
    visualTheme,
    { timeout: timeout() },
  );
  try {
    await page.waitForFunction(
      (expectedTheme) => {
        const root = globalThis.document.documentElement;
        return (
          root.getAttribute("data-theme") === expectedTheme &&
          root.getAttribute("data-reduce-motion") === "true" &&
          root.getAttribute("data-reduced-transparency") === "true" &&
          root.getAttribute("data-high-contrast") === "true"
        );
      },
      visualTheme,
      { timeout: timeout() },
    );
  } catch (error) {
    const state = await page.evaluate(() => {
      const root = globalThis.document.documentElement;
      return {
        theme: root.getAttribute("data-theme"),
        themeMode: root.getAttribute("data-theme-mode"),
        reducedMotion: root.getAttribute("data-reduce-motion"),
        reducedTransparency: root.getAttribute("data-reduced-transparency"),
        highContrast: root.getAttribute("data-high-contrast"),
      };
    });
    throw new Error(`外观偏好未收敛：${JSON.stringify(state)}`, { cause: error });
  }
  const evidence = await page.evaluate(() => ({
    theme: globalThis.document.documentElement.getAttribute("data-theme"),
    reducedMotion: globalThis.document.documentElement.getAttribute("data-reduce-motion"),
    reducedTransparency: globalThis.document.documentElement.getAttribute(
      "data-reduced-transparency",
    ),
    highContrast: globalThis.document.documentElement.getAttribute("data-high-contrast"),
  }));
  if (captureSettingsEvidence) {
    await captureVisualEvidence(
      page,
      `implementation-settings-center-${visualTheme}-native-current.png`,
    );
  }
  const responsive = captureSettingsEvidence ? await captureResponsiveVisualEvidence(page) : [];
  await settings.getByRole("button", { name: "返回应用", exact: true }).click();
  await conversationSurface(page).waitFor({ state: "visible", timeout: timeout() });
  return { status: "passed", ...evidence, responsive };
}

/**
 * 每次都从产品公开的设置入口重新定位 Appearance；设置 Shell 可以隐藏工作区，但不得卸载
 * Editor/Terminal owner，因此矩阵不会通过直接写 localStorage 或 DOM attribute 绕过真实控件。
 */
async function openThemeMatrixAppearanceSettings(page, deadline) {
  const timeout = () => Math.max(1, deadline - Date.now());
  const settings = page.getByRole("region", { name: "设置页面", exact: true });
  if (!(await settings.isVisible().catch(() => false))) {
    await page.getByRole("button", { name: "设置", exact: true }).click({ timeout: timeout() });
  }
  await settings.waitFor({ state: "visible", timeout: timeout() });
  await settings.getByRole("tab", { name: "外观", exact: true }).click({ timeout: timeout() });
  return settings;
}

/**
 * 只通过 Radix combobox/option 改变一个外观维度，并等待 document authority 收敛；
 * 选择当前值时允许控件不触发回调，但根属性仍必须与请求一致。
 */
async function selectThemeMatrixAppearanceValue(
  page,
  settings,
  { controlName, optionName, rootAttribute, value },
  deadline,
) {
  const timeout = () => Math.max(1, deadline - Date.now());
  const trigger = settings.getByRole("combobox", { name: controlName, exact: true });
  await trigger.waitFor({ state: "visible", timeout: timeout() });
  await page.waitForFunction(
    (accessibleName) => {
      const candidate = [...globalThis.document.querySelectorAll('[role="combobox"]')].find(
        (element) => element.getAttribute("aria-label") === accessibleName,
      );
      return (
        candidate !== undefined &&
        !candidate.hasAttribute("disabled") &&
        candidate.getAttribute("aria-disabled") !== "true"
      );
    },
    controlName,
    { timeout: timeout() },
  );
  await trigger.click({ timeout: timeout() });
  await page.getByRole("option", { name: optionName, exact: true }).click({ timeout: timeout() });
  await page.waitForFunction(
    ({ attribute, expected }) =>
      globalThis.document.documentElement.getAttribute(attribute) === expected,
    { attribute: rootAttribute, expected: value },
    { timeout: timeout() },
  );
  await page.waitForFunction(
    (accessibleName) => {
      const candidate = [...globalThis.document.querySelectorAll('[role="combobox"]')].find(
        (element) => element.getAttribute("aria-label") === accessibleName,
      );
      return (
        candidate !== undefined &&
        !candidate.hasAttribute("disabled") &&
        candidate.getAttribute("aria-disabled") !== "true"
      );
    },
    controlName,
    { timeout: timeout() },
  );
}

/**
 * 从真实历史列表读取并再次选择当前项目 Thread，再打开该 Thread 的 Files Editor 与 xterm；
 * 首次启动可能已呈现空会话，故不假设历史必须为空，也不通过 DOM/store 注入绕过会话准入。
 * 后续主题切换只保存当前 WebView 节点引用，并以 loopback 请求数为零证明视觉验收没有触发模型调用。
 * @author kongweiguang
 */
async function prepareThemeMatrixWorkbench(page, deadline, signal, providerFixture) {
  if (!Array.isArray(providerFixture?.attempts)) {
    throw new Error("Theme Matrix 缺少本地 loopback Provider 请求计数");
  }
  const providerAttemptsBefore = providerFixture.attempts.length;
  if (providerAttemptsBefore !== 0) {
    throw new Error("Theme Matrix 建立 Thread 前已有 loopback Provider 请求");
  }
  let stepDeadline = deadline;
  /**
   * 每个真实工作台准备步骤使用独立上限并输出稳定阶段名，避免单个缺失控件耗尽整轮矩阵期限。
   */
  const beginStep = (name) => {
    stepDeadline = Math.min(deadline, Date.now() + 45_000);
    console.log(`JA_E2E_THEME_MATRIX_STAGE ${name}`);
  };
  /** 把 Playwright 等待绑定到当前步骤，而不是复用十五分钟全局期限。 */
  const timeout = () => Math.max(1, stepDeadline - Date.now());
  beginStep("runtime_ready");
  await waitForRuntimeReady(page, stepDeadline, signal);
  beginStep("project_selection");
  const selectedProject = page.locator(
    '[aria-label="项目列表"] button[data-scope-kind="project"][aria-current="page"]',
  );
  if ((await selectedProject.count()) === 0) {
    await page.getByRole("button", { name: "添加项目", exact: true }).click({ timeout: timeout() });
  }
  await selectedProject.waitFor({ state: "visible", timeout: timeout() });

  beginStep("thread_selection");
  const readyBeforeThread = await waitForRuntimeReady(page, stepDeadline, signal);
  const threadId = await currentThreadId(page, stepDeadline, signal);
  await selectProjectThreadById(page, threadId, stepDeadline, signal);
  const selectedThreadId = await currentThreadId(page, stepDeadline, signal);
  const authority = await page.evaluate(async (expectedThreadId) => {
    const invoke = globalThis.__TAURI_INTERNALS__?.invoke;
    if (typeof invoke !== "function") return { status: "bridge_unavailable" };
    try {
      const snapshot = await invoke("ja_thread_read", {
        input: { threadId: expectedThreadId, limit: 1 },
      });
      return {
        status: "resolved",
        threadId:
          snapshot !== null && typeof snapshot === "object" && typeof snapshot.threadId === "string"
            ? snapshot.threadId
            : null,
        revision:
          snapshot !== null &&
          typeof snapshot === "object" &&
          Number.isSafeInteger(snapshot.revision)
            ? snapshot.revision
            : null,
      };
    } catch (error) {
      const candidate = error !== null && typeof error === "object" ? error : {};
      return {
        status: "rejected",
        errorCode: typeof candidate.code === "string" ? candidate.code : "unknown",
      };
    }
  }, threadId);
  const readyAfterThread = await waitForRuntimeReady(page, stepDeadline, signal);
  if (
    threadId !== selectedThreadId ||
    authority.status !== "resolved" ||
    authority.threadId !== threadId ||
    readyBeforeThread.generation !== readyAfterThread.generation ||
    readyBeforeThread.serverInstanceId !== readyAfterThread.serverInstanceId
  ) {
    throw new Error(
      `Theme Matrix Thread、权威快照与 Runtime Ready 身份不一致：${JSON.stringify({
        threadId,
        selectedThreadId,
        authority,
        readyBeforeThread,
        readyAfterThread,
      })}`,
    );
  }
  if (providerFixture.attempts.length !== providerAttemptsBefore) {
    throw new Error("Theme Matrix 创建空 Thread 意外发起了 loopback Provider 请求");
  }
  const threadEvidence = {
    threadId,
    authorityRevision: authority.revision,
    runtimeGeneration: readyAfterThread.generation,
    serverInstanceId: readyAfterThread.serverInstanceId,
    providerRequests: providerFixture.attempts.length,
  };

  beginStep("workbench_files");
  const workbench = await currentThreadWorkbenchInspector(page);
  if (!(await workbench.isVisible().catch(() => false))) {
    await page
      .getByRole("button", { name: "显示工作区面板", exact: true })
      .click({ timeout: timeout() });
  }
  await workbench.waitFor({ state: "visible", timeout: timeout() });
  await chooseWorkbenchTool(page, "文件", stepDeadline);
  const filesWorkspace = workbench.getByRole("region", { name: "文件工作区", exact: true });
  const sampleNode = filesWorkspace
    .getByRole("tree", { name: "工作区文件", exact: true })
    .locator('[data-path="sample.ts"]');
  await sampleNode.waitFor({ state: "visible", timeout: timeout() });
  await sampleNode.click({ timeout: timeout() });
  const editor = filesWorkspace.getByRole("region", { name: "编辑文件 sample.ts", exact: true });
  await editor.waitFor({ state: "visible", timeout: timeout() });
  const content = editor.locator('.cm-content[contenteditable="true"]');
  await content.click({ timeout: timeout() });
  await content.press("Control+A");
  beginStep("editor_baseline");
  const editorBaseline = await editor.evaluate((editorElement) => {
    /** FNV-1a 只证明隔离 fixture 内容稳定，不把编辑器文本复制到持久证据。 */
    const digest = (value) => {
      let hash = 0x811c9dc5;
      for (let index = 0; index < value.length; index += 1) {
        hash ^= value.charCodeAt(index);
        hash = Math.imul(hash, 0x01000193);
      }
      return (hash >>> 0).toString(16).padStart(8, "0");
    };
    const editorContent = editorElement.querySelector('.cm-content[contenteditable="true"]');
    const editorText = editorContent?.textContent ?? "";
    const selectionText = globalThis.getSelection()?.toString() ?? "";
    if (editorText.length === 0 || selectionText.length === 0) {
      throw new Error("Theme Matrix 无法建立 CodeMirror 内容与选择基线");
    }
    return {
      editorLength: editorText.length,
      editorDigest: digest(editorText),
      selectionLength: selectionText.length,
      selectionDigest: digest(selectionText),
    };
  });

  beginStep("workbench_terminal");
  await chooseWorkbenchTool(page, "终端", stepDeadline);
  const terminalWorkspace = workbench.getByRole("region", { name: "终端工作区", exact: true });
  await terminalWorkspace.waitFor({ state: "visible", timeout: timeout() });
  const terminalTab = await activeTerminalTab(terminalWorkspace, stepDeadline);
  const pane = terminalTab.panel.locator(".ja-terminal-pane[data-pane-id]").first();
  await pane
    .locator(".ja-terminal-pane-state")
    .getByText("运行中", { exact: true })
    .waitFor({ state: "visible", timeout: timeout() });
  await pane.locator(".xterm").waitFor({ state: "visible", timeout: timeout() });
  await page.waitForFunction(
    () => {
      const candidate = globalThis.document.querySelector(
        '.ja-terminal-workspace [role="tabpanel"]:not([hidden]) .ja-terminal-pane[data-pane-id]',
      );
      return (
        candidate?.getAttribute("data-terminal-session-id") &&
        candidate.getAttribute("data-terminal-session-generation")
      );
    },
    undefined,
    { timeout: timeout() },
  );

  beginStep("workbench_baseline");
  const workbenchBaseline = await page.evaluate((initialEditor) => {
    /** FNV-1a 只证明隔离 fixture 画面内容稳定，不把终端路径或文本复制到持久证据。 */
    const digest = (value) => {
      let hash = 0x811c9dc5;
      for (let index = 0; index < value.length; index += 1) {
        hash ^= value.charCodeAt(index);
        hash = Math.imul(hash, 0x01000193);
      }
      return (hash >>> 0).toString(16).padStart(8, "0");
    };
    const editorRegion = globalThis.document.querySelector('[aria-label="编辑文件 sample.ts"]');
    const editor = editorRegion?.querySelector(".cm-editor");
    const editorContent = editor?.querySelector('.cm-content[contenteditable="true"]');
    const terminalPane = globalThis.document.querySelector(
      '.ja-terminal-workspace [role="tabpanel"]:not([hidden]) .ja-terminal-pane[data-pane-id]',
    );
    const xterm = terminalPane?.querySelector(".xterm");
    const terminalRows = xterm?.querySelector(".xterm-rows")?.textContent ?? "";
    if (
      !(editor instanceof globalThis.HTMLElement) ||
      !(editorContent instanceof globalThis.HTMLElement) ||
      !(terminalPane instanceof globalThis.HTMLElement) ||
      !(xterm instanceof globalThis.HTMLElement)
    ) {
      throw new Error("Theme Matrix 缺少 Editor 或 xterm 真实节点");
    }
    const baseline = {
      ...initialEditor,
      terminalLength: terminalRows.length,
      terminalDigest: digest(terminalRows),
      paneId: terminalPane.getAttribute("data-pane-id"),
      sessionId: terminalPane.getAttribute("data-terminal-session-id"),
      sessionGeneration: terminalPane.getAttribute("data-terminal-session-generation"),
    };
    globalThis.__JA_E2E_THEME_MATRIX_WORKBENCH__ = {
      editor,
      editorContent,
      terminalPane,
      xterm,
      baseline,
    };
    return baseline;
  }, editorBaseline);
  if (providerFixture.attempts.length !== providerAttemptsBefore) {
    throw new Error("Theme Matrix Workbench 准备意外发起了 loopback Provider 请求");
  }
  return { ...workbenchBaseline, thread: threadEvidence };
}

/**
 * 对当前主界面读取五主题关键 token、overflow、CodeMirror/xterm 热更新与原生 session identity；
 * 自定义色值先经浏览器规范化，避免 hex/rgb 表示差异造成伪失败。
 */
async function captureThemeMatrixFrame(page, client, expected, viewport, reducedMotion, deadline) {
  try {
    await client.send("Emulation.setDeviceMetricsOverride", {
      ...viewport,
      deviceScaleFactor: 1,
      mobile: false,
    });
    await page.emulateMedia({
      forcedColors: "none",
      reducedMotion: reducedMotion ? "reduce" : "no-preference",
    });
    await page.waitForFunction(
      ({ palette, mode, motion }) => {
        const root = globalThis.document.documentElement;
        return (
          root.dataset["palette"] === palette &&
          root.dataset["theme"] === mode &&
          root.dataset["themeMode"] === mode &&
          globalThis.matchMedia("(prefers-reduced-motion: reduce)").matches === motion
        );
      },
      { palette: expected.palette, mode: expected.mode, motion: reducedMotion },
      { timeout: Math.max(1, deadline - Date.now()) },
    );
    const evidence = await page.evaluate(
      ({ palette, mode, anchors, motion }) => {
        const root = globalThis.document.documentElement;
        const styles = globalThis.getComputedStyle(root);
        const refs = globalThis.__JA_E2E_THEME_MATRIX_WORKBENCH__;
        /** 浏览器自身解析 CSS Color，使 token 审计不依赖源码的大小写与简写形式。 */
        const canonicalColor = (value) => {
          const probe = globalThis.document.createElement("span");
          probe.style.color = value;
          globalThis.document.body.append(probe);
          const result = globalThis.getComputedStyle(probe).color;
          probe.remove();
          return result;
        };
        const token = (name) => styles.getPropertyValue(name).trim();
        const requiredTokens = [
          "--ja-background",
          "--ja-content",
          "--ja-surface",
          "--ja-control",
          "--ja-selected",
          "--ja-border",
          "--ja-border-strong",
          "--ja-foreground",
          "--ja-foreground-muted",
          "--ja-accent",
          "--ja-accent-emphasis",
          "--ja-on-accent",
          "--ja-focus",
          "--ja-editor-background",
          "--ja-window-surface",
          "--ja-syntax-keyword",
          "--ja-diff-inserted",
          "--ja-scrollbar-thumb",
          "--ja-terminal-background",
          "--ja-terminal-foreground",
          "--ja-terminal-ansi-red",
          "--ja-terminal-ansi-blue",
        ];
        const missingTokens = requiredTokens.filter((name) => token(name).length === 0);
        const actualAnchors = {
          background: canonicalColor(token("--ja-background")),
          content: canonicalColor(token("--ja-content")),
          editor: canonicalColor(token("--ja-editor-background")),
          accent: canonicalColor(token("--ja-accent")),
        };
        const expectedAnchors = Object.fromEntries(
          Object.entries(anchors).map(([name, value]) => [name, canonicalColor(value)]),
        );
        const terminalToken = canonicalColor(token("--ja-terminal-background"));
        const viewportNode = refs?.xterm?.querySelector(".xterm-viewport");
        const xtermBackground =
          viewportNode instanceof globalThis.HTMLElement
            ? globalThis.getComputedStyle(viewportNode).backgroundColor
            : "";
        const conversationHeading = globalThis.document.querySelector(".ja-conversation-heading");
        const conversationTitle = conversationHeading?.querySelector("strong");
        const conversationIcon = conversationHeading?.querySelector("svg");
        const conversationHeadingColor =
          conversationHeading === null
            ? ""
            : globalThis.getComputedStyle(conversationHeading).color;
        const conversationTitleColor =
          conversationTitle === null || conversationTitle === undefined
            ? ""
            : globalThis.getComputedStyle(conversationTitle).color;
        const conversationIconColor =
          conversationIcon === null || conversationIcon === undefined
            ? ""
            : globalThis.getComputedStyle(conversationIcon).color;
        const horizontalOverflow = [globalThis.document.documentElement, globalThis.document.body]
          .filter((element) => element.scrollWidth > element.clientWidth + 1)
          .map((element) => ({
            tag: element.tagName,
            clientWidth: element.clientWidth,
            scrollWidth: element.scrollWidth,
          }));
        return {
          palette: root.dataset["palette"],
          theme: root.dataset["theme"],
          themeMode: root.dataset["themeMode"],
          reducedTransparency: root.dataset["reducedTransparency"],
          reducedMotionMedia: globalThis.matchMedia("(prefers-reduced-motion: reduce)").matches,
          width: globalThis.innerWidth,
          height: globalThis.innerHeight,
          missingTokens,
          actualAnchors,
          expectedAnchors,
          terminalToken,
          xtermBackground,
          conversationHeadingColor,
          conversationTitleColor,
          conversationIconColor,
          horizontalOverflow,
          editorConnected: refs?.editor?.isConnected === true,
          editorSameNode:
            refs?.editor ===
            globalThis.document.querySelector('[aria-label="编辑文件 sample.ts"] .cm-editor'),
          editorTheme: refs?.editor?.getAttribute("data-ja-code-theme"),
          terminalConnected: refs?.terminalPane?.isConnected === true,
          terminalSameNode:
            refs?.terminalPane ===
            globalThis.document.querySelector(
              '.ja-terminal-workspace [role="tabpanel"]:not([hidden]) .ja-terminal-pane[data-pane-id]',
            ),
          xtermSameNode: refs?.xterm === refs?.terminalPane?.querySelector(".xterm"),
          paneId: refs?.terminalPane?.getAttribute("data-pane-id"),
          sessionId: refs?.terminalPane?.getAttribute("data-terminal-session-id"),
          sessionGeneration: refs?.terminalPane?.getAttribute("data-terminal-session-generation"),
          expectedMotion: motion,
          expectedPalette: palette,
          expectedMode: mode,
        };
      },
      { ...expected, motion: reducedMotion },
    );
    if (
      evidence.palette !== expected.palette ||
      evidence.theme !== expected.mode ||
      evidence.themeMode !== expected.mode ||
      evidence.reducedTransparency !== "true" ||
      evidence.reducedMotionMedia !== reducedMotion ||
      evidence.width !== viewport.width ||
      evidence.height !== viewport.height ||
      evidence.missingTokens.length !== 0 ||
      JSON.stringify(evidence.actualAnchors) !== JSON.stringify(evidence.expectedAnchors) ||
      evidence.horizontalOverflow.length !== 0 ||
      !evidence.editorConnected ||
      !evidence.editorSameNode ||
      evidence.editorTheme !== `${expected.palette}-${expected.mode}` ||
      !evidence.terminalConnected ||
      !evidence.terminalSameNode ||
      !evidence.xtermSameNode ||
      evidence.conversationHeadingColor.length === 0 ||
      evidence.conversationHeadingColor !== evidence.conversationTitleColor ||
      evidence.conversationHeadingColor !== evidence.conversationIconColor ||
      evidence.xtermBackground !== evidence.terminalToken
    ) {
      throw new Error(`Theme Matrix frame 不完整：${JSON.stringify(evidence)}`);
    }
    await captureVisualEvidence(
      page,
      `theme-matrix-${expected.palette}-${expected.mode}-${reducedMotion ? "reduced" : "normal"}-${viewport.width}x${viewport.height}.png`,
    );
    return evidence;
  } finally {
    await page
      .emulateMedia({ forcedColors: "none", reducedMotion: "no-preference" })
      .catch(() => undefined);
    await client.send("Emulation.clearDeviceMetricsOverride").catch(() => undefined);
  }
}

/**
 * 执行五 Palette x 浅深 x viewport x motion 的真实桌面矩阵；每次从设置页切换后回到同一
 * Workbench 验证重组件身份，最后 reload 只验证本地持久化恢复，并用 loopback 计数拒绝 Provider 调用。
 * @author kongweiguang
 */
async function runThemeMatrixAcceptanceSession(
  page,
  deadline,
  diagnostics,
  signal,
  recordStage,
  providerFixture,
) {
  recordStage?.("theme_matrix:workbench");
  const baseline = await prepareThemeMatrixWorkbench(page, deadline, signal, providerFixture);
  const configurationWritesBefore = {
    replace: await tauriInvokeCount(page, "ja_configuration_replace"),
    patch: await tauriInvokeCount(page, "ja_configuration_patch"),
    reset: await tauriInvokeCount(page, "ja_configuration_reset"),
  };
  let settings = await openThemeMatrixAppearanceSettings(page, deadline);
  const reducedTransparency = settings.getByRole("switch", {
    name: "降低透明度",
    exact: true,
  });
  await reducedTransparency.waitFor({
    state: "visible",
    timeout: Math.max(1, deadline - Date.now()),
  });
  await page.waitForFunction(
    () => {
      const candidate = globalThis.document.querySelector(
        '[role="switch"][aria-label="降低透明度"]',
      );
      return (
        candidate !== null &&
        !candidate.hasAttribute("disabled") &&
        candidate.getAttribute("aria-disabled") !== "true"
      );
    },
    undefined,
    { timeout: Math.max(1, deadline - Date.now()) },
  );
  if ((await reducedTransparency.getAttribute("aria-checked")) !== "true") {
    await reducedTransparency.click({ timeout: Math.max(1, deadline - Date.now()) });
  }
  await page.waitForFunction(
    () =>
      globalThis.document.documentElement.dataset["reducedTransparency"] === "true" &&
      globalThis.document
        .querySelector('[role="switch"][aria-label="降低透明度"]')
        ?.getAttribute("aria-checked") === "true" &&
      !globalThis.document
        .querySelector('[role="switch"][aria-label="降低透明度"]')
        ?.hasAttribute("disabled") &&
      globalThis.document
        .querySelector('[role="switch"][aria-label="降低透明度"]')
        ?.getAttribute("aria-disabled") !== "true",
    undefined,
    { timeout: Math.max(1, deadline - Date.now()) },
  );
  const frames = [];
  const client = await page.context().newCDPSession(page);
  try {
    for (const palette of themeMatrixPalettes) {
      for (const mode of themeMatrixModes) {
        recordStage?.(`theme_matrix:${palette.value}_${mode.value}`);
        await selectThemeMatrixAppearanceValue(
          page,
          settings,
          {
            controlName: "配色主题",
            optionName: palette.label,
            rootAttribute: "data-palette",
            value: palette.value,
          },
          deadline,
        );
        await selectThemeMatrixAppearanceValue(
          page,
          settings,
          {
            controlName: "外观模式",
            optionName: mode.label,
            rootAttribute: "data-theme-mode",
            value: mode.value,
          },
          deadline,
        );
        await page.waitForFunction(
          ({ expectedPalette, expectedMode }) => {
            const root = globalThis.document.documentElement;
            return (
              root.dataset["palette"] === expectedPalette && root.dataset["theme"] === expectedMode
            );
          },
          { expectedPalette: palette.value, expectedMode: mode.value },
          { timeout: Math.max(1, deadline - Date.now()) },
        );
        await settings.getByRole("button", { name: "返回应用", exact: true }).click();
        await conversationSurface(page).waitFor({
          state: "visible",
          timeout: Math.max(1, deadline - Date.now()),
        });
        await chooseWorkbenchTool(page, "文件", deadline);
        await page
          .locator('[aria-label="编辑文件 sample.ts"] .cm-editor')
          .waitFor({ state: "visible", timeout: Math.max(1, deadline - Date.now()) });
        await page.waitForFunction(
          (expectedTheme) =>
            globalThis.document
              .querySelector('[aria-label="编辑文件 sample.ts"] .cm-editor')
              ?.getAttribute("data-ja-code-theme") === expectedTheme,
          `${palette.value}-${mode.value}`,
          { timeout: Math.max(1, deadline - Date.now()) },
        );
        await chooseWorkbenchTool(page, "终端", deadline);
        const expected = {
          palette: palette.value,
          mode: mode.value,
          anchors: themeMatrixAnchors[palette.value][mode.value],
        };
        for (const viewport of themeMatrixViewports) {
          for (const motion of [false, true]) {
            frames.push(
              await captureThemeMatrixFrame(page, client, expected, viewport, motion, deadline),
            );
          }
        }
        settings = await openThemeMatrixAppearanceSettings(page, deadline);
      }
    }
  } finally {
    await page
      .emulateMedia({ forcedColors: "none", reducedMotion: "no-preference" })
      .catch(() => undefined);
    await client.send("Emulation.clearDeviceMetricsOverride").catch(() => undefined);
    // Direct CDP 与 WebView2 target 共用生命周期；与 runner 其它矩阵一致，不显式 detach 唯一 renderer。
  }
  await settings.getByRole("button", { name: "返回应用", exact: true }).click();
  await chooseWorkbenchTool(page, "文件", deadline);
  const editorContent = page.locator(
    '[aria-label="编辑文件 sample.ts"] .cm-content[contenteditable="true"]',
  );
  await editorContent.evaluate((element) => element.focus());
  await page.waitForFunction(
    ({ expectedLength, expectedDigest }) => {
      /** 与初始基线使用相同的有界 digest，证明 CodeMirror model selection 在失焦后恢复。 */
      const digest = (value) => {
        let hash = 0x811c9dc5;
        for (let index = 0; index < value.length; index += 1) {
          hash ^= value.charCodeAt(index);
          hash = Math.imul(hash, 0x01000193);
        }
        return (hash >>> 0).toString(16).padStart(8, "0");
      };
      const selection = globalThis.getSelection()?.toString() ?? "";
      return selection.length === expectedLength && digest(selection) === expectedDigest;
    },
    { expectedLength: baseline.selectionLength, expectedDigest: baseline.selectionDigest },
    { timeout: Math.max(1, deadline - Date.now()) },
  );
  await chooseWorkbenchTool(page, "终端", deadline);
  const finalWorkbench = await page.evaluate(() => {
    /** 与 prepare 阶段相同的摘要确保内容比较不把隔离路径写入 evidence。 */
    const digest = (value) => {
      let hash = 0x811c9dc5;
      for (let index = 0; index < value.length; index += 1) {
        hash ^= value.charCodeAt(index);
        hash = Math.imul(hash, 0x01000193);
      }
      return (hash >>> 0).toString(16).padStart(8, "0");
    };
    const refs = globalThis.__JA_E2E_THEME_MATRIX_WORKBENCH__;
    const editorText = refs?.editorContent?.textContent ?? "";
    const terminalText = refs?.xterm?.querySelector(".xterm-rows")?.textContent ?? "";
    return {
      editorSameNode:
        refs?.editor ===
        globalThis.document.querySelector('[aria-label="编辑文件 sample.ts"] .cm-editor'),
      editorLength: editorText.length,
      editorDigest: digest(editorText),
      terminalSameNode: refs?.terminalPane?.querySelector(".xterm") === refs?.xterm,
      terminalLength: terminalText.length,
      terminalDigest: digest(terminalText),
      paneId: refs?.terminalPane?.getAttribute("data-pane-id"),
      sessionId: refs?.terminalPane?.getAttribute("data-terminal-session-id"),
      sessionGeneration: refs?.terminalPane?.getAttribute("data-terminal-session-generation"),
    };
  });
  if (
    !finalWorkbench.editorSameNode ||
    finalWorkbench.editorLength !== baseline.editorLength ||
    finalWorkbench.editorDigest !== baseline.editorDigest ||
    !finalWorkbench.terminalSameNode ||
    finalWorkbench.terminalLength < baseline.terminalLength ||
    finalWorkbench.paneId !== baseline.paneId ||
    finalWorkbench.sessionId !== baseline.sessionId ||
    finalWorkbench.sessionGeneration !== baseline.sessionGeneration
  ) {
    throw new Error(`Theme Matrix 热切换破坏 Workbench 状态：${JSON.stringify(finalWorkbench)}`);
  }
  const configurationWritesAfter = {
    replace: await tauriInvokeCount(page, "ja_configuration_replace"),
    patch: await tauriInvokeCount(page, "ja_configuration_patch"),
    reset: await tauriInvokeCount(page, "ja_configuration_reset"),
  };
  if (JSON.stringify(configurationWritesAfter) !== JSON.stringify(configurationWritesBefore)) {
    throw new Error("Theme Matrix 本地偏好错误触发 App Server configuration 保存");
  }
  const consoleErrors = diagnostics.console.filter((entry) => entry.startsWith("error:"));
  if (consoleErrors.length !== 0 || diagnostics.pageErrors.length !== 0) {
    throw new Error(
      `Theme Matrix 出现 WebView 控制台错误：${JSON.stringify({ consoleErrors, pageErrors: diagnostics.pageErrors })}`,
    );
  }
  recordStage?.("theme_matrix:reload");
  await page.reload({ waitUntil: "domcontentloaded", timeout: Math.max(1, deadline - Date.now()) });
  await waitForRuntimeReady(page, deadline, signal);
  await page.waitForFunction(
    () => {
      const root = globalThis.document.documentElement;
      return (
        root.dataset["palette"] === "claude" &&
        root.dataset["theme"] === "dark" &&
        root.dataset["themeMode"] === "dark" &&
        root.dataset["reducedTransparency"] === "true"
      );
    },
    undefined,
    { timeout: Math.max(1, deadline - Date.now()) },
  );
  const reloadConsoleErrors = diagnostics.console.filter((entry) => entry.startsWith("error:"));
  if (reloadConsoleErrors.length !== 0 || diagnostics.pageErrors.length !== 0) {
    throw new Error(
      `Theme Matrix reload 出现 WebView 控制台错误：${JSON.stringify({ consoleErrors: reloadConsoleErrors, pageErrors: diagnostics.pageErrors })}`,
    );
  }
  const providerRequestCount = providerFixture.attempts.length;
  if (providerRequestCount !== 0) {
    throw new Error(`Theme Matrix 外观验收不应触发 Provider 请求，实际 ${providerRequestCount}`);
  }
  return {
    status: "passed",
    combinations: themeMatrixPalettes.length * themeMatrixModes.length,
    frameCount: frames.length,
    viewports: themeMatrixViewports,
    motionModes: ["normal", "reduced"],
    reducedTransparency: true,
    consoleErrorCount: 0,
    configurationWrites: configurationWritesAfter,
    thread: baseline.thread,
    providerRequestCount,
    workbench: {
      editorPreserved: true,
      editorSelectionPreserved: true,
      terminalPreserved: true,
      paneId: finalWorkbench.paneId,
      sessionId: finalWorkbench.sessionId,
      sessionGeneration: finalWorkbench.sessionGeneration,
    },
    reload: { palette: "claude", theme: "dark", themeMode: "dark", reducedTransparency: true },
    frames,
  };
}

/**
 * 在发送前安装只观察工作过程 Commentary 的 MutationObserver；不保留正文，只记录首次非空文本
 * 的单调时钟和长度，使门禁能证明 WebView2 在 terminal 事件之前已把增量放进正确 Surface。
 */
async function beginRealtimeProcessObservation(page) {
  await page.evaluate(() => {
    globalThis.__JA_E2E_PROCESS_OBSERVER__?.disconnect?.();
    globalThis.__JA_E2E_PROCESS_OBSERVATIONS__ = [];
    const sample = () => {
      const process = globalThis.document.querySelector(
        '.ja-work-step--commentary[data-role="commentary"]',
      );
      const length = process?.textContent?.length ?? 0;
      const samples = Array.isArray(globalThis.__JA_E2E_PROCESS_OBSERVATIONS__)
        ? globalThis.__JA_E2E_PROCESS_OBSERVATIONS__
        : [];
      if (length > 0 && samples.length === 0) {
        samples.push({ observedAt: globalThis.performance.now(), length });
      }
      globalThis.__JA_E2E_PROCESS_OBSERVATIONS__ = samples;
    };
    const observer = new globalThis.MutationObserver(sample);
    observer.observe(globalThis.document.body, {
      childList: true,
      subtree: true,
      characterData: true,
    });
    globalThis.__JA_E2E_PROCESS_OBSERVER__ = observer;
    sample();
  });
}

/**
 * 同时要求协议 delta 顺序和 WorkProcess DOM 时序先于同 Turn terminal；只比较本地单调时钟和业务
 * identity，不复制 Provider 文本，从而可用于真实 OpenAI/Anthropic 流而不泄漏内容。终态跨
 * Rust event queue 异步到达，因此在同一 Turn deadline 内等待，不能用一次瞬时采样制造竞态。
 */
async function assertRealtimeProcessBeforeTerminal(page, deadline, signal) {
  let events;
  let terminal;
  await waitForCondition(
    "带本地时钟的 turn/terminal",
    async () => {
      events = await captureRawTauriEvents(page);
      terminal = events.findLast(
        (event) => event.method === "turn/terminal" && event.observedAt !== undefined,
      );
      return terminal?.turnId !== undefined && terminal.observedAt !== undefined;
    },
    deadline,
    signal,
  );
  const delta = events.find(
    (event) =>
      event.method === "assistant/text-delta" &&
      event.turnId === terminal.turnId &&
      event.observedAt !== undefined,
  );
  const process = await page.evaluate(() =>
    Array.isArray(globalThis.__JA_E2E_PROCESS_OBSERVATIONS__)
      ? globalThis.__JA_E2E_PROCESS_OBSERVATIONS__[0]
      : undefined,
  );
  if (
    delta?.observedAt === undefined ||
    delta.observedAt >= terminal.observedAt ||
    !Number.isFinite(process?.observedAt) ||
    process.observedAt >= terminal.observedAt ||
    !Number.isSafeInteger(process?.length) ||
    process.length < 1
  ) {
    throw new Error(
      `增量未在 terminal 前进入 WebView2 工作过程：${JSON.stringify({ deltaAt: delta?.observedAt, processAt: process?.observedAt, terminalAt: terminal.observedAt })}`,
    );
  }
  return {
    status: "passed",
    turnId: terminal.turnId,
    deltaBeforeTerminal: true,
    processBeforeTerminal: true,
  };
}

/**
 * 只调整本轮已复验身份的 HWND，以覆盖要求的桌面矩阵。
 * 每一行同时记录原生窗口与 renderer 事实，避免把 CDP 设备模拟误当成 Windows/WebView2 验收。
 * renderer 工作台采样限定当前 owner，后台保留 Host 不计入几何、launcher 或 Tab 状态。
 */
async function captureWorkbenchNativeMatrix(page, stateLabel, identity, deadline, signal) {
  const evidence = [];
  const workbench = await currentThreadWorkbenchInspector(page);
  // 1920 CSS 行与 2560x1392@1 参考值属于视觉 QA 合同，在当前 2560x1392 显示器的 150% 缩放下
  // 无法物理实现。功能冒烟仍覆盖两个真实 HWND 尺寸；显式启用的视觉运行保留完整固定矩阵，
  // 因而继续保持故障关闭。
  const nativeMatrix =
    visualEvidenceDirectory === undefined
      ? responsiveRendererMatrix.filter(({ width }) => width <= 1440)
      : responsiveRendererMatrix;
  try {
    for (const viewport of nativeMatrix) {
      const nativeViewport = await resizeOwnedNativeViewport(
        page,
        identity,
        viewport,
        deadline,
        signal,
      );
      const metrics = await workbench.evaluate((inspector) => {
        /** 将实时 DOMRect 转为可安全写入 JSON 的 CSS 像素证据行。 */
        const bounds = (element) => {
          const rect = element?.getBoundingClientRect();
          return rect === undefined
            ? null
            : { x: rect.x, y: rect.y, width: rect.width, height: rect.height };
        };
        const workbenchRoot = inspector.querySelector(".ja-workbench");
        const newPanel = inspector.querySelector('[data-tab-panel="new"]');
        return {
          innerWidth: globalThis.innerWidth,
          innerHeight: globalThis.innerHeight,
          devicePixelRatio: globalThis.devicePixelRatio,
          scrollWidth: globalThis.document.documentElement.scrollWidth,
          navigation: bounds(globalThis.document.querySelector(".ja-navigation-shell")),
          agent: bounds(globalThis.document.querySelector(".ja-main")),
          workbench: bounds(inspector),
          launcherVisible:
            inspector.querySelector(
              '[data-tab-panel="new"]:not([hidden]) .ja-workbench-launcher',
            ) !== null,
          workbenchState:
            workbenchRoot === null
              ? null
              : {
                  activeTab: workbenchRoot.getAttribute("data-active-tab"),
                  openTabs: workbenchRoot.getAttribute("data-open-tabs"),
                },
          inspectorVisible: inspector?.getAttribute("data-visible") ?? null,
          newPanel:
            newPanel === null
              ? null
              : {
                  hidden: newPanel.hasAttribute("hidden"),
                  inert: newPanel.hasAttribute("inert"),
                  bounds: bounds(newPanel),
                },
          renderedTabs: [...inspector.querySelectorAll(".ja-workbench-tab-shell[data-tab]")].map(
            (tab) => ({
              tab: tab.getAttribute("data-tab"),
              state: tab.getAttribute("data-state"),
            }),
          ),
        };
      });
      if (!metrics.launcherVisible || metrics.workbench === null || metrics.workbench.width <= 1) {
        throw new Error(
          `${viewport.width}x${viewport.height} renderer 矩阵缺少可见工作台 launcher：${JSON.stringify(metrics)}`,
        );
      }
      if (metrics.scrollWidth > metrics.innerWidth + 1) {
        throw new Error(
          `${viewport.width}x${viewport.height} renderer 工作台出现水平溢出 ${metrics.scrollWidth}/${metrics.innerWidth}`,
        );
      }
      await captureVisualEvidence(
        page,
        `implementation-codex-workbench-${stateLabel}-${visualTheme}-native-${viewport.width}x${viewport.height}.png`,
      );
      evidence.push({
        label: `${viewport.width}x${viewport.height}`,
        state: stateLabel,
        surface: "native_window",
        nativeWindow: true,
        window: nativeViewport,
        ...metrics,
      });
    }
  } finally {
    await maximizeOwnedNativeWindow(page, identity, deadline, signal);
  }
  return evidence;
}

/**
 * 为整轮运行创建唯一取消源；阶段 deadline 不得重置，否则卡住的第二次启动可能超出 runner 总预算。
 */
function createDeadline(label, durationMs) {
  const controller = new globalThis.AbortController();
  const deadline = Date.now() + durationMs;
  const timer = globalThis.setTimeout(() => {
    controller.abort(new Error(`${label} 超过 ${durationMs}ms`));
  }, durationMs);
  return {
    signal: controller.signal,
    deadline,
    cancel: () => globalThis.clearTimeout(timer),
  };
}

/**
 * 将 AbortSignal 原因转换为普通 Error，使失败运行仍进入既有 summary writer，
 * 而不是产生未处理的 abort。
 */
function throwIfAborted(signal) {
  if (signal?.aborted) {
    const reason = signal.reason;
    throw reason instanceof Error ? reason : new Error(String(reason ?? "E2E 已取消"));
  }
}

/**
 * 让轮询可取消，使 cleanup 能立即唤醒，既不遗留 timer，也无需等待下一次一秒进程轮询。
 */
function waitForDelay(durationMs, signal) {
  return new Promise((resolvePromise, rejectPromise) => {
    let timer;
    /** 取消时同步解除 timer/listener，避免短轮询在阶段清理后继续回调。 */
    const onAbort = () => {
      globalThis.clearTimeout(timer);
      signal?.removeEventListener("abort", onAbort);
      rejectPromise(signal.reason instanceof Error ? signal.reason : new Error("E2E 已取消"));
    };
    if (signal?.aborted) {
      onAbort();
      return;
    }
    timer = globalThis.setTimeout(() => {
      signal?.removeEventListener("abort", onAbort);
      resolvePromise();
    }, durationMs);
    signal?.addEventListener("abort", onAbort, { once: true });
  });
}

/**
 * 为不支持原生 AbortSignal 参数的 Playwright 操作设置上界；拒绝后仍由阶段 cleanup 回收产品进程。
 */
function raceWithSignal(operation, signal) {
  if (signal?.aborted) {
    return Promise.reject(signal.reason ?? new Error("E2E 已取消"));
  }
  return new Promise((resolvePromise, rejectPromise) => {
    /** Playwright 操作不可取消时先拒绝外层等待，真实资源仍交给统一 cleanup。 */
    const onAbort = () => rejectPromise(signal.reason ?? new Error("E2E 已取消"));
    signal?.addEventListener("abort", onAbort, { once: true });
    Promise.resolve()
      .then(operation)
      .then(
        (value) => {
          signal?.removeEventListener("abort", onAbort);
          resolvePromise(value);
        },
        (error) => {
          signal?.removeEventListener("abort", onAbort);
          rejectPromise(error);
        },
      );
  });
}

/**
 * Node 支持时，将整轮 abort 与本地短诊断预算组合；旧 runtime 下的回退仍确保本地 deadline 有界。
 */
function combineSignals(signals) {
  const active = signals.filter((signal) => signal !== undefined);
  if (active.length <= 1) {
    return active[0];
  }
  if (typeof globalThis.AbortSignal?.any === "function") {
    return globalThis.AbortSignal.any(active);
  }
  return active[active.length - 1];
}

/**
 * 先规范化刚创建的随机根，再派生各目录；Rust 会在 sidecar 参数中编码规范路径，必须与 E2E owner 比较共用同一拼写。
 * 随机后缀还使 workspace identity 与开发者现有 Ja 历史数据库彼此独立。
 * @author kongweiguang
 */
export async function createRunDirectories(temporaryDirectory = tmpdir()) {
  const createdRoot = await mkdtemp(join(temporaryDirectory, "ja-desktop-e2e-"));
  let root;
  try {
    root = realpathSync.native(createdRoot);
  } catch (error) {
    Object.defineProperty(error, "e2eRoot", { value: createdRoot, enumerable: false });
    throw error;
  }
  const workspace = join(root, "workspace");
  const settings = join(root, "settings");
  // 正式运行 Host 从隔离 USERPROFILE 解析唯一 Ja Home；正式 fixture 写入同一目录。
  // UDF prime 另用随机子根，避免其未就绪的 sidecar 与正式 App Server 共享 owner/endpoint。
  const home = join(settings, ".ja");
  const data = join(home, "data");
  const webview = join(root, "webview");
  const runtime = join(root, "runtime");
  const appData = join(root, "appdata");
  const roaming = join(appData, "roaming");
  const local = join(appData, "local");
  const desktop = join(settings, "Desktop");
  try {
    await Promise.all([
      mkdir(workspace),
      // Windows common file dialog 会从隔离 USERPROFILE 解析 Desktop Known Folder；缺失时会先弹出
      // “位置不可用”错误框，使 picker 验收误中错误 owner。递归创建同时建立 profile 根。
      mkdir(desktop, { recursive: true }),
      mkdir(home, { recursive: true }),
      mkdir(data, { recursive: true }),
      mkdir(webview),
      mkdir(runtime),
      mkdir(roaming, { recursive: true }),
      mkdir(local, { recursive: true }),
    ]);
  } catch (error) {
    Object.defineProperty(error, "e2eRoot", { value: root, enumerable: false });
    throw error;
  }
  return {
    root,
    workspace,
    settings,
    home,
    data,
    webview,
    runtime,
    appData,
    roaming,
    local,
  };
}

/**
 * 为 UDF 预热建立与正式运行分离的配置、数据、日志和 Runtime 根；只复用同一轮 WebView2 profile，
 * 使预热期间未发布 endpoint 的 sidecar 仍可由随机 prime 子树严格归属并回收。
 * @author kongweiguang
 */
export async function createProfilePrimeDirectories(directories) {
  const createdRoot = join(directories.root, "ja-desktop-e2e-profile-prime");
  await mkdir(createdRoot);
  const root = realpathSync.native(createdRoot);
  const settings = join(root, "settings");
  const home = join(settings, ".ja");
  const prime = {
    root,
    workspace: join(root, "workspace"),
    settings,
    home,
    data: join(home, "data"),
    webview: directories.webview,
    runtime: join(root, "runtime"),
    appData: join(root, "appdata"),
    roaming: join(root, "appdata", "roaming"),
    local: join(root, "appdata", "local"),
    desktop: join(settings, "Desktop"),
  };
  await Promise.all([
    mkdir(prime.workspace),
    mkdir(prime.desktop, { recursive: true }),
    mkdir(prime.home, { recursive: true }),
    mkdir(prime.data, { recursive: true }),
    mkdir(prime.runtime),
    mkdir(prime.roaming, { recursive: true }),
    mkdir(prime.local, { recursive: true }),
  ]);
  assertLaunchRuntimeRoot(prime);
  runtimeIsolationDirectories(prime);
  return prime;
}

/**
 * 从本轮隔离 Java 日志中提取稳定异常类别；只保留 WARN/ERROR 与 Agent loop 自身诊断，避免
 * 将 Provider 正文、Workspace 内容或大段框架启动日志复制进 E2E summary。
 */
async function captureManagedJavaDiagnostics(directories) {
  const logPath = resolve(directories.settings, ".ja", "logs", "java", "app-server.log");
  const root = `${resolve(directories.root)}\\`.toLowerCase();
  if (!logPath.toLowerCase().startsWith(root)) {
    throw new Error("Java 诊断日志不属于本轮隔离根");
  }
  try {
    const metadata = await stat(logPath);
    if (!metadata.isFile() || metadata.size > 4 * 1024 * 1024) {
      return { status: "unavailable", reason: "invalid_size" };
    }
    const lines = (await readFile(logPath, "utf8"))
      .split(/\r?\n/u)
      .filter(
        (line) =>
          line.includes("AgentTurnExecution") ||
          line.includes(" WARN ") ||
          line.includes(" ERROR "),
      )
      .slice(-80)
      .map((line) => redact(line, directories));
    return { status: "captured", lines };
  } catch {
    return { status: "missing", lines: [] };
  }
}

const taskMetricSourceDefinitions = Object.freeze([
  {
    name: "task_active_count",
    eventMarker: "event=task_active_count",
    fields: Object.freeze(["active_count"]),
    sourcePath:
      "ja-agent/ja-app-server/src/main/java/io/github/kongweiguang/ja/collaboration/application/service/TaskCoordinator.java",
  },
  {
    name: "workspace_write_lease_wait",
    eventMarker: "event=workspace_write_lease_wait",
    fields: Object.freeze(["wait_ms"]),
    sourcePath:
      "ja-agent/ja-app-server/src/main/java/io/github/kongweiguang/ja/conversation/application/loop/WorkspaceWriteLeaseCoordinator.java",
  },
  {
    name: "task_recovery_suspended",
    eventMarker: "event=task_recovery_suspended",
    fields: Object.freeze(["suspended_count"]),
    sourcePath:
      "ja-agent/ja-app-server/src/main/java/io/github/kongweiguang/ja/infrastructure/persistence/repository/task/TaskRecoveryPersistence.java",
  },
  {
    name: "task_progress_coalesced_total",
    eventMarker: 'metric = "task_progress_coalesced_total"',
    fields: Object.freeze(["count"]),
    sourcePath: "crates/ja-runtime/src/app_server_process/client/session/events.rs",
  },
]);

/**
 * 在启动桌面进程前读取唯一的四项现行指标源码；固定相对路径使失效路径直接失败，
 * 而不是把缺失源码记成 unknown/null 后继续执行昂贵真窗验收。
 * @author kongweiguang
 */
export async function readTaskMetricDefinitionChecks() {
  return Promise.all(
    taskMetricSourceDefinitions.map(async (definition) => {
      let source;
      try {
        source = await readFile(join(repoRoot, ...definition.sourcePath.split("/")), "utf8");
      } catch (error) {
        const reason = error?.code === "ENOENT" ? "缺失" : "不可读取";
        throw new Error(`Task 指标源码预检失败：${definition.name}（${reason}）`);
      }
      return {
        name: definition.name,
        sourcePath: definition.sourcePath,
        fields: [...definition.fields],
        present: source.includes(definition.eventMarker),
        fieldsPresent: definition.fields.every(
          (field) => source.includes(`${field}=`) || source.includes(`${field} =`),
        ),
      };
    }),
  );
}

/**
 * 只接受与源码定义逐项同序且全部明确为 true 的结果；部分、未知或被篡改的检查不得变成通过。
 * @author kongweiguang
 */
export function taskMetricDefinitionChecksAreValid(checks) {
  return (
    Array.isArray(checks) &&
    checks.length === taskMetricSourceDefinitions.length &&
    taskMetricSourceDefinitions.every((expected, index) => {
      const actual = checks[index];
      return (
        actual !== null &&
        typeof actual === "object" &&
        JSON.stringify(Object.keys(actual).sort()) ===
          JSON.stringify(["fields", "fieldsPresent", "name", "present", "sourcePath"]) &&
        actual.name === expected.name &&
        actual.sourcePath === expected.sourcePath &&
        Array.isArray(actual.fields) &&
        JSON.stringify(actual.fields) === JSON.stringify(expected.fields) &&
        actual.present === true &&
        actual.fieldsPresent === true
      );
    })
  );
}

/**
 * 复用运行前已核验的四项 event/field 合同，从隔离日志只提取事件名；原始日志、prompt、
 * Secret 与绝对路径都不进入 summary，运行时仍必须证明 active Task 指标被写入。
 * @author kongweiguang
 */
async function captureTaskMetricEvidence(directories, scenario, definitionChecks) {
  if (!taskMetricDefinitionChecksAreValid(definitionChecks)) {
    throw new Error("Task 指标源码合同在运行期间失效");
  }
  const logPath = resolve(directories.home, "logs", "java", "app-server.log");
  let metricLines = [];
  try {
    const metadata = await stat(logPath);
    if (metadata.isFile() && metadata.size <= 4 * 1024 * 1024) {
      const names = new Set(taskMetricSourceDefinitions.map((definition) => definition.name));
      metricLines = (await readFile(logPath, "utf8"))
        .split(/\r?\n/u)
        .filter((line) => [...names].some((name) => line.includes(`event=${name}`)));
    }
  } catch {
    metricLines = [];
  }
  const forbidden = [
    scenario.prompt,
    scenario.followupPrompt,
    scenario.agentRootPrompt,
    scenario.levelOneBrief,
    scenario.levelTwoBrief,
    scenario.levelThreeBrief,
    "JA_TITLE_LOOPBACK_ONLY",
    resolve(directories.root),
  ];
  return {
    definitions: definitionChecks.map(({ name, present, fieldsPresent }) => ({
      name,
      present,
      fieldsPresent,
    })),
    runtimeEventNames: taskMetricSourceDefinitions
      .filter((definition) => metricLines.some((line) => line.includes(`event=${definition.name}`)))
      .map((definition) => definition.name),
    runtimeRedactionValid: forbidden.every(
      (value) => typeof value !== "string" || !metricLines.some((line) => line.includes(value)),
    ),
  };
}

/**
 * 只读取一次显式启用的自定义供应商配置，验证不含凭据的 loopback URL，并在复制任何子进程环境前
 * 从 process.env 删除密钥。Wire 协议由 API 规范独立选择，供应商名称不参与路由。
 */
function readRealProviderConfig() {
  if (!configuredRealProviderMode) return undefined;
  if (process.env.JA_E2E_KEEP_TEMP === "1") {
    throw new Error("真实 Provider 验收禁止保留临时目录");
  }
  const apiKey = process.env.JA_E2E_REAL_PROVIDER_API_KEY ?? "";
  delete process.env.JA_E2E_REAL_PROVIDER_API_KEY;
  const baseUrl = process.env.JA_E2E_REAL_PROVIDER_BASE_URL?.trim() || "http://localhost:60842/v1";
  const model = process.env.JA_E2E_REAL_PROVIDER_MODEL?.trim() || "gpt-5.6-sol";
  const name = process.env.JA_E2E_REAL_PROVIDER_NAME?.trim() || "E2E Real Provider";
  delete process.env.JA_E2E_REAL_PROVIDER_NAME;
  const api = process.env.JA_E2E_REAL_PROVIDER_API?.trim() || "openai_responses";
  delete process.env.JA_E2E_REAL_PROVIDER_API;
  const configureViaUi = process.env.JA_E2E_CONFIGURE_VIA_UI === "1";
  delete process.env.JA_E2E_CONFIGURE_VIA_UI;
  let parsed;
  try {
    parsed = new URL(baseUrl);
  } catch {
    throw new Error("真实 Provider Base URL 无效");
  }
  const loopback =
    parsed.hostname === "localhost" ||
    parsed.hostname === "127.0.0.1" ||
    parsed.hostname === "[::1]";
  if (
    parsed.protocol !== "http:" ||
    !loopback ||
    parsed.username !== "" ||
    parsed.password !== "" ||
    parsed.search !== "" ||
    parsed.hash !== ""
  ) {
    throw new Error("真实 Provider 只接受无凭据、无查询参数的 loopback HTTP URL");
  }
  if (apiKey.length < 1 || apiKey.length > 8_192 || /[\0\r\n]/u.test(apiKey)) {
    throw new Error("真实 Provider API Key 长度或字符不合法");
  }
  if (model.length < 1 || model.length > 256 || /[\0\r\n]/u.test(model)) {
    throw new Error("真实 Provider 模型名称不合法");
  }
  if (name.length < 1 || name.length > 512 || /[\0\r\n]/u.test(name)) {
    throw new Error("真实 Provider 名称不合法");
  }
  if (!new Set(["anthropic_messages", "openai_chat_completions", "openai_responses"]).has(api)) {
    throw new Error("真实 Provider API 规范不受 v1 支持");
  }
  sensitiveRedactions.add(apiKey);
  sensitiveRedactions.add(parsed.href.replace(/\/$/u, ""));
  return {
    apiKey,
    baseUrl: parsed.href.replace(/\/$/u, ""),
    model,
    name,
    api,
    configureViaUi,
  };
}

/**
 * 以分片目录和有界并发写入小文件，避免 fixture 自身用一次性 Promise 风暴制造与产品无关的内存峰值。
 */
async function writeWorkspaceSwitchFileFixture(directory, count, signal) {
  const shardSize = 250;
  const batchSize = 64;
  await mkdir(directory, { recursive: true });
  for (let shardStart = 0; shardStart < count; shardStart += shardSize) {
    throwIfAborted(signal);
    const shard = join(directory, `shard-${String(shardStart / shardSize).padStart(3, "0")}`);
    await mkdir(shard, { recursive: true });
    const shardEnd = Math.min(count, shardStart + shardSize);
    for (let batchStart = shardStart; batchStart < shardEnd; batchStart += batchSize) {
      throwIfAborted(signal);
      const batchEnd = Math.min(shardEnd, batchStart + batchSize);
      await Promise.all(
        Array.from({ length: batchEnd - batchStart }, (_, offset) =>
          writeFile(
            join(shard, `item-${String(batchStart + offset).padStart(6, "0")}.txt`),
            "x\n",
            "utf8",
          ),
        ),
      );
    }
  }
}

/** Git 的 `-z` 输出没有路径转义；只计非空记录可同时正确覆盖 Unicode 与空格路径。 */
function nulSeparatedPathCount(value) {
  return String(value ?? "")
    .split("\0")
    .filter((entry) => entry.length > 0).length;
}

/**
 * 为 Files、search 和四类原生 Git Review 构造已提交、分支与脏改动；性能模式额外创建
 * 已被 Git 明确认定为 ignored 的 `.codex-target` 与普通 untracked 小文件。
 */
async function initializeWorkspaceFixture(
  workspace,
  gitCommand,
  signal,
  { workspaceSwitchPerformance = false } = {},
) {
  const sample = join(workspace, "sample.ts");
  const agentChangeFixtureDirectory = join(workspace, ".ja-fixture");
  const agentChangeFixture = join(agentChangeFixtureDirectory, "change.txt");
  const visibleDirectoryFixture = join(workspace, "folder-fixture");
  const overflowDirectoryFixture = join(workspace, "overflow-fixture");
  await Promise.all([
    mkdir(agentChangeFixtureDirectory, { recursive: true }),
    mkdir(visibleDirectoryFixture, { recursive: true }),
    mkdir(overflowDirectoryFixture, { recursive: true }),
  ]);
  await writeFile(agentChangeFixture, "before\n", "utf8");
  await writeFile(
    join(visibleDirectoryFixture, "child.txt"),
    "visible directory fixture\n",
    "utf8",
  );
  await Promise.all(
    Array.from({ length: 64 }, (_, index) =>
      writeFile(
        join(overflowDirectoryFixture, `item-${String(index).padStart(3, "0")}.txt`),
        `overflow ${index}\n`,
        "utf8",
      ),
    ),
  );
  await writeFile(sample, 'export const greeting = "hello";\n', "utf8");
  if (workspaceSwitchPerformance) {
    await writeFile(join(workspace, ".gitignore"), "/.codex-target/\n", "utf8");
  }
  const runGit = async (args) =>
    execFileAsync(gitCommand, args, {
      cwd: workspace,
      windowsHide: true,
      maxBuffer: 2 * 1024 * 1024,
      timeout: snapshotTimeoutMs,
      signal,
    });
  await runGit(["init"]);
  await runGit(["checkout", "-b", "main"]);
  await runGit(["config", "user.name", "Ja E2E"]);
  await runGit(["config", "user.email", "ja-e2e@localhost"]);
  const initialTrackedPaths = [
    "sample.ts",
    ".ja-fixture/change.txt",
    "folder-fixture/child.txt",
    "overflow-fixture",
  ];
  if (workspaceSwitchPerformance) initialTrackedPaths.push(".gitignore");
  await runGit(["add", ...initialTrackedPaths]);
  await runGit(["commit", "-m", "fixture"]);
  await runGit(["branch", "review-base"]);
  await writeFile(join(workspace, "committed-change.txt"), "Ja committed review fixture\n", "utf8");
  await runGit(["add", "committed-change.txt"]);
  await runGit(["commit", "-m", "review fixture head"]);
  await writeFile(
    sample,
    'export const greeting = "hello from Ja";\nexport const answer = 42;\n',
    "utf8",
  );
  await writeFile(join(workspace, "new-file.txt"), "Ja workbench search fixture\n", "utf8");
  await writeFile(join(workspace, "trash-cancel.txt"), "Ja trash cancel fixture\n", "utf8");
  await writeFile(join(workspace, "trash-me.txt"), "Ja trash opt-in fixture\n", "utf8");
  await writeFile(
    join(workspace, attachmentFixtureFile),
    "Ja managed attachment fixture\n",
    "utf8",
  );
  await writeFile(
    join(workspace, unavailableAttachmentFixtureFile),
    "Ja unavailable attachment fixture with distinct content\n",
    "utf8",
  );
  await writeFile(
    join(workspace, businessFixtureFile),
    [
      "# 退款业务规则",
      "",
      "- 客户代号：ORBIT-7429",
      "- 超过 500 元的退款必须由两名审批人共同批准。",
      "- 审批应在 48 小时内完成。",
      "- 验收输出：ORBIT-7429|DUAL_APPROVAL|48H",
      "",
    ].join("\n"),
    "utf8",
  );
  if (!workspaceSwitchPerformance) return undefined;

  await Promise.all([
    writeWorkspaceSwitchFileFixture(
      join(workspace, ".codex-target"),
      workspaceSwitchIgnoredFixtureCount,
      signal,
    ),
    writeWorkspaceSwitchFileFixture(
      join(workspace, "workspace-switch-untracked"),
      workspaceSwitchUntrackedFixtureCount,
      signal,
    ),
  ]);
  const [ignored, untracked] = await Promise.all([
    runGit([
      "ls-files",
      "--others",
      "--ignored",
      "--exclude-standard",
      "-z",
      "--",
      ".codex-target",
    ]),
    runGit([
      "ls-files",
      "--others",
      "--exclude-standard",
      "-z",
      "--",
      "workspace-switch-untracked",
    ]),
  ]);
  const ignoredCodexTargetFiles = nulSeparatedPathCount(ignored.stdout);
  const ordinaryUntrackedFiles = nulSeparatedPathCount(untracked.stdout);
  if (
    ignoredCodexTargetFiles !== workspaceSwitchIgnoredFixtureCount ||
    ordinaryUntrackedFiles !== workspaceSwitchUntrackedFixtureCount
  ) {
    throw new Error(
      `workspace switch fixture 分类不完整：${JSON.stringify({ ignoredCodexTargetFiles, ordinaryUntrackedFiles })}`,
    );
  }
  return {
    ignoredCodexTargetFiles,
    ordinaryUntrackedFiles,
    ignoredRoot: ".codex-target",
    untrackedRoot: "workspace-switch-untracked",
    fileBytes: 2,
  };
}

/** 启动带请求计数器的 loopback 页面，用于证明 Preview 确实加载了真实子 WebView。 */
async function startPreviewFixture() {
  let requests = 0;
  const server = createHttpServer((request, response) => {
    requests += 1;
    response.writeHead(200, {
      "content-type": "text/html; charset=utf-8",
      "cache-control": "no-store",
    });
    response.end(
      "<!doctype html><html><head><title>Ja Preview Fixture</title></head><body><main>JA_PREVIEW_OK</main></body></html>",
    );
  });
  await new Promise((resolvePromise, rejectPromise) => {
    server.once("error", rejectPromise);
    server.listen(0, "127.0.0.1", resolvePromise);
  });
  const address = server.address();
  if (typeof address !== "object" || address === null) {
    server.close();
    throw new Error("无法启动 Preview fixture");
  }
  return {
    url: `http://127.0.0.1:${address.port}/`,
    requestCount: () => requests,
    close: () => new Promise((resolvePromise) => server.close(() => resolvePromise())),
  };
}

