/**
 * 只把 ServerResponse 已 flush 或客户端真实断开视为 Provider 交换终态。`responded` 仅表示
 * fixture 已开始发送，不能代替传输收敛，否则 keep-alive 与半关闭会让负向断言产生假阳性。
 */
function titleFixtureExchangeFinished(attempt) {
  return attempt?.finished === true || attempt?.disconnected === true;
}

/** 创建一次性可查询释放门，测试失败关闭时重复 release 也保持幂等。 */
function createFixtureGate() {
  let released = false;
  let releasePromise;
  const promise = new Promise((resolvePromise) => {
    releasePromise = resolvePromise;
  });
  return {
    promise,
    released: () => released,
    release: () => {
      if (released) return;
      released = true;
      releasePromise();
    },
  };
}

/** 读取有界 JSON 请求；Provider fixture 不保留请求正文、Header 或凭据。 */
async function readBoundedFixtureJson(request) {
  const chunks = [];
  let size = 0;
  for await (const chunk of request) {
    size += chunk.length;
    // 本轮修改压力夹具的 Tool history 会携带约 3 MiB 的精确参数；8 MiB 仍是严格上限，
    // 且只在该独立 focused mode 放宽，避免其它 Provider 场景无意扩大内存面。
    const maximumBytes = turnChangeReviewAcceptanceMode ? 8 * 1024 * 1024 : 2 * 1024 * 1024;
    if (size > maximumBytes) throw new Error("fixture request exceeded byte limit");
    chunks.push(chunk);
  }
  return JSON.parse(Buffer.concat(chunks).toString("utf8"));
}

/** 构造 OpenAI Responses 最小 envelope，字段与生产 Adapter 的严格 SSE 解析合同一致。 */
function titleFixtureResponse(responseId, status, output, includeUsage) {
  const response = {
    id: responseId,
    created_at: 0,
    model: "ja-title-loopback-model",
    object: "response",
    output,
    parallel_tool_calls: true,
    tool_choice: "auto",
    tools: [],
    status,
  };
  if (includeUsage) {
    response.usage = {
      input_tokens: 5,
      input_tokens_details: { cached_tokens: 0, cache_write_tokens: 0 },
      output_tokens: 5,
      output_tokens_details: { reasoning_tokens: 0 },
      total_tokens: 10,
    };
  }
  return response;
}

/** 将一个严格 Responses 事件编码为 SSE；不使用隐式换行或 JSON pretty-print。 */
function titleFixtureEvent(type, sequence, payload) {
  return `event: ${type}\ndata: ${JSON.stringify({
    type,
    sequence_number: sequence,
    ...payload,
  })}\n\n`;
}

/** 生成自然结束且带完整 usage 的文本流，使自动标题不会因缺少审计用量而回退。 */
function titleFixtureTextStream(text, requestNumber) {
  const responseId = `resp_title_e2e_${requestNumber}`;
  const itemId = `message_title_e2e_${requestNumber}`;
  const finalItem = {
    id: itemId,
    type: "message",
    role: "assistant",
    status: "completed",
    content: [{ type: "output_text", text, annotations: [], logprobs: [] }],
  };
  return [
    titleFixtureEvent("response.created", 0, {
      response: titleFixtureResponse(responseId, "in_progress", [], false),
    }),
    titleFixtureEvent("response.output_text.delta", 1, {
      content_index: 0,
      delta: text,
      item_id: itemId,
      logprobs: [],
      output_index: 0,
    }),
    titleFixtureEvent("response.output_text.done", 2, {
      content_index: 0,
      item_id: itemId,
      output_index: 0,
      text,
    }),
    titleFixtureEvent("response.completed", 3, {
      response: titleFixtureResponse(responseId, "completed", [finalItem], true),
    }),
  ].join("");
}

/** 固定 MCP meta-tool 始终接收一套参数；远端参数只在 call 的 argumentsJson 中编码。 */
function runtimeRefreshMetaToolArguments(action, argumentsJson = null) {
  return {
    action,
    argumentsJson,
    offset: null,
    query: null,
    serverId: runtimeRefreshFixtureContract.serverId,
    toolName: runtimeRefreshFixtureContract.toolName,
  };
}

/**
 * 按 Provider 原生结果块和稳定调用 ID 读取正文；单靠 type 名或相邻消息不能证明结果属于目标 Tool。
 */
/** 只按稳定 call ID 收集 Provider 原生结果项，保留零条或多条结果供验收拒绝。 */
function runtimeRefreshNativeToolResultItems(payload, api, callId) {
  return api === "openai_responses"
    ? (Array.isArray(payload?.input) ? payload.input : []).filter(
        (item) => item?.type === "function_call_output" && item.call_id === callId,
      )
    : api === "anthropic_messages"
      ? (Array.isArray(payload?.messages) ? payload.messages : [])
          .flatMap((message) => (Array.isArray(message?.content) ? message.content : []))
          .filter((item) => item?.type === "tool_result" && item.tool_use_id === callId)
      : [];
}

/** 按 Provider 原生结果块和稳定调用 ID 读取正文；保留非文本值供调用方给出精确失败诊断。 */
function runtimeRefreshNativeToolResult(payload, api, callId) {
  const results = runtimeRefreshNativeToolResultItems(payload, api, callId);
  if (results.length !== 1) return undefined;
  const result = results[0];
  const content = api === "openai_responses" ? result.output : result.content;
  return { result, content };
}

/** 校验生产 Tool 投影的字符数、SHA-256 与有序诊断尾行后读取正文，避免误拒绝合法失败结果。 */
export function runtimeRefreshParseAuditedText(value) {
  if (typeof value !== "string") return { valid: false, reason: "not_text" };
  const footer = value.match(
    /\n\[characters=(\d+) sha256=([a-f0-9]{64})\](?:\n\[exit_code=(-?\d+)\])?(?:\n\[error=([^\r\n]*)\])?$/u,
  );
  if (footer === null) return { valid: false, reason: "missing_footer" };

  const body = value.slice(0, footer.index);
  const expectedCharacters = Number(footer[1]);
  const exitCode = footer[3] === undefined ? null : Number(footer[3]);
  const error = footer[4] ?? null;
  const codePointCountValid =
    Number.isSafeInteger(expectedCharacters) && Array.from(body).length === expectedCharacters;
  const sha256Valid = createHash("sha256").update(body, "utf8").digest("hex") === footer[2];
  if (!codePointCountValid || !sha256Valid) {
    return {
      valid: false,
      reason: "footer_mismatch",
      codePointCountValid,
      sha256Valid,
      exitCode,
      error,
    };
  }
  return { valid: true, content: body, codePointCountValid, sha256Valid, exitCode, error };
}

/** 只有先通过生产完整性尾注验证的正文才能进入结构化 JSON 断言。 */
function runtimeRefreshParseAuditedJson(value) {
  const audited = runtimeRefreshParseAuditedText(value);
  if (!audited.valid) return audited;
  try {
    return { ...audited, value: JSON.parse(audited.content) };
  } catch {
    return { ...audited, valid: false, reason: "invalid_json" };
  }
}

/**
 * describe 是只读结果，须在按 call ID 关联后核验目录身份和真实远端参数 Schema，不能只搜描述文本。
 */
function runtimeRefreshDescribeResultMatches(payload, api, callId, revision) {
  const output = runtimeRefreshNativeToolResult(payload, api, callId);
  if (output === undefined) return false;
  const audited = runtimeRefreshParseAuditedJson(output.content);
  if (!audited.valid) return false;
  const described = audited.value;
  const schema = described?.inputSchema;
  const properties = schema?.properties;
  const valueType = revision === 1 ? "string" : "integer";
  return (
    described?.serverId === runtimeRefreshFixtureContract.serverId &&
    described?.toolName === runtimeRefreshFixtureContract.toolName &&
    described?.description === `Runtime refresh fixture revision ${revision}` &&
    schema?.type === "object" &&
    schema.additionalProperties === false &&
    JSON.stringify(Object.keys(properties ?? {}).sort()) === '["value"]' &&
    properties?.value?.type === valueType &&
    properties.value.description ===
      (revision === 1 ? "revision one string" : "revision two integer") &&
    JSON.stringify(schema.required) === '["value"]'
  );
}

/** 只保存 Responses 输入项与合成 describe 结果的结构摘要，定位续请求投影故障而不留存正文。 */
function runtimeRefreshDescribeResultDiagnostics(payload, callId, revision) {
  const input = Array.isArray(payload?.input) ? payload.input : [];
  const functionOutputs = input.filter((item) => item?.type === "function_call_output");
  const matchingOutputs = functionOutputs.filter((item) => item.call_id === callId);
  const summary = {
    inputItemTypes: input.map((item) => (typeof item?.type === "string" ? item.type : "invalid")),
    functionCallCount: input.filter((item) => item?.type === "function_call").length,
    functionCallOutputCount: functionOutputs.length,
    matchingOutputCount: matchingOutputs.length,
    matchingOutputType: matchingOutputs.length === 1 ? typeof matchingOutputs[0].output : null,
    parsedDescribe: null,
  };
  if (matchingOutputs.length !== 1 || typeof matchingOutputs[0].output !== "string") {
    return summary;
  }

  const audited = runtimeRefreshParseAuditedJson(matchingOutputs[0].output);
  summary.outputAudit = {
    valid: audited.valid,
    reason: audited.reason ?? null,
    codePointCountValid: audited.codePointCountValid ?? null,
    sha256Valid: audited.sha256Valid ?? null,
  };
  if (!audited.valid) {
    summary.parsedDescribe = { validJson: false };
    return summary;
  }

  const described = audited.value;
  const schema = described?.inputSchema;
  const properties = schema?.properties;
  summary.parsedDescribe = {
    validJson: true,
    rootIsObject: described !== null && typeof described === "object" && !Array.isArray(described),
    serverIdMatches: described?.serverId === runtimeRefreshFixtureContract.serverId,
    toolNameMatches: described?.toolName === runtimeRefreshFixtureContract.toolName,
    descriptionMatches: described?.description === `Runtime refresh fixture revision ${revision}`,
    schemaType: typeof schema?.type === "string" ? schema.type : null,
    additionalProperties:
      typeof schema?.additionalProperties === "boolean" ? schema.additionalProperties : null,
    propertyNames:
      properties !== null && typeof properties === "object" && !Array.isArray(properties)
        ? Object.keys(properties).sort()
        : [],
    valueType: typeof properties?.value?.type === "string" ? properties.value.type : null,
    valueDescriptionMatches:
      properties?.value?.description ===
      (revision === 1 ? "revision one string" : "revision two integer"),
    required: Array.isArray(schema?.required) ? schema.required : null,
  };
  return summary;
}

/** 按 Responses 原生 function_call 格式表达固定 meta-tool 动作，不暴露远端工具名。 */
function runtimeRefreshOpenAiToolStream(callId, action, argumentsJson = null) {
  const item = {
    id: `item_${callId}`,
    type: "function_call",
    call_id: callId,
    name: runtimeRefreshFixtureContract.metaToolName,
    arguments: JSON.stringify(runtimeRefreshMetaToolArguments(action, argumentsJson)),
  };
  return [
    titleFixtureEvent("response.output_item.added", 0, {
      output_index: 0,
      item: { ...item, arguments: "" },
    }),
    titleFixtureEvent("response.function_call_arguments.done", 1, {
      item_id: item.id,
      arguments: item.arguments,
      output_index: 0,
    }),
    titleFixtureEvent("response.output_item.done", 2, { output_index: 0, item }),
    titleFixtureEvent("response.completed", 3, {
      response: titleFixtureResponse(`resp_${callId}`, "completed", [item], true),
    }),
  ].join("");
}

/** 为旧 Responses Profile 正常收口，保留 Usage 证据以区分 Tool 失败与 Turn 失败。 */
function runtimeRefreshOpenAiFinalStream(text, requestNumber) {
  const itemId = `message_runtime_refresh_${requestNumber}`;
  const finalItem = {
    id: itemId,
    type: "message",
    role: "assistant",
    status: "completed",
    content: [{ type: "output_text", text, annotations: [], logprobs: [] }],
  };
  return [
    titleFixtureEvent("response.created", 0, {
      response: titleFixtureResponse(
        `resp_runtime_refresh_${requestNumber}`,
        "in_progress",
        [],
        false,
      ),
    }),
    titleFixtureEvent("response.output_text.delta", 1, {
      content_index: 0,
      delta: text,
      item_id: itemId,
      logprobs: [],
      output_index: 0,
    }),
    titleFixtureEvent("response.output_text.done", 2, {
      content_index: 0,
      item_id: itemId,
      output_index: 0,
      text,
    }),
    titleFixtureEvent("response.completed", 3, {
      response: titleFixtureResponse(
        `resp_runtime_refresh_${requestNumber}`,
        "completed",
        [finalItem],
        true,
      ),
    }),
  ].join("");
}

/** Anthropic SSE 每帧同时写 event 与 data，避免测试依赖客户端对缺失 event 的宽松兼容。 */
function runtimeRefreshAnthropicEvent(type, payload) {
  return `event: ${type}\ndata: ${JSON.stringify({ type, ...payload })}\n\n`;
}

/** 第二 Turn 先 describe 新目录；读操作不应越过新 admission 所冻结的目录快照。 */
function runtimeRefreshAnthropicDescribeStream() {
  return [
    runtimeRefreshAnthropicEvent("message_start", {
      message: {
        id: "msg_runtime_refresh_v2_describe",
        type: "message",
        role: "assistant",
        content: [],
        model: "runtime-new-model",
        stop_reason: null,
        stop_sequence: null,
        usage: { input_tokens: 9, output_tokens: 0 },
      },
    }),
    runtimeRefreshAnthropicEvent("content_block_start", {
      index: 0,
      content_block: {
        type: "tool_use",
        id: "call_runtime_refresh_v2_describe",
        name: runtimeRefreshFixtureContract.metaToolName,
        input: runtimeRefreshMetaToolArguments("describe"),
      },
    }),
    runtimeRefreshAnthropicEvent("content_block_stop", { index: 0 }),
    runtimeRefreshAnthropicEvent("message_delta", {
      delta: { stop_reason: "tool_use", stop_sequence: null },
      usage: { output_tokens: 3 },
    }),
    runtimeRefreshAnthropicEvent("message_stop", {}),
  ].join("");
}

/** 第二 Turn 的调用请求保留私有 thinking/signature，供同一 Profile continuation 验证。 */
function runtimeRefreshAnthropicToolStream() {
  return [
    runtimeRefreshAnthropicEvent("message_start", {
      message: {
        id: "msg_runtime_refresh_tool",
        type: "message",
        role: "assistant",
        content: [],
        model: "runtime-new-model",
        stop_reason: null,
        stop_sequence: null,
        usage: { input_tokens: 13, output_tokens: 0 },
      },
    }),
    runtimeRefreshAnthropicEvent("content_block_start", {
      index: 0,
      content_block: { type: "thinking", thinking: "" },
    }),
    runtimeRefreshAnthropicEvent("content_block_delta", {
      index: 0,
      delta: { type: "thinking_delta", thinking: runtimeRefreshFixtureContract.thinking },
    }),
    runtimeRefreshAnthropicEvent("content_block_delta", {
      index: 0,
      delta: { type: "signature_delta", signature: runtimeRefreshFixtureContract.signature },
    }),
    runtimeRefreshAnthropicEvent("content_block_stop", { index: 0 }),
    runtimeRefreshAnthropicEvent("content_block_start", {
      index: 1,
      content_block: {
        type: "tool_use",
        id: "call_runtime_refresh_v2_call",
        name: runtimeRefreshFixtureContract.metaToolName,
        input: runtimeRefreshMetaToolArguments("call", JSON.stringify({ value: 42 })),
      },
    }),
    runtimeRefreshAnthropicEvent("content_block_stop", { index: 1 }),
    runtimeRefreshAnthropicEvent("message_delta", {
      delta: { stop_reason: "tool_use", stop_sequence: null },
      usage: { output_tokens: 7 },
    }),
    runtimeRefreshAnthropicEvent("message_stop", {}),
  ].join("");
}

/** 第二 Turn 的终请求故意省略 Usage；UI 必须展示最新 UNKNOWN，不能回退先前 KNOWN。 */
function runtimeRefreshAnthropicFinalStream(text) {
  return [
    runtimeRefreshAnthropicEvent("message_start", {
      message: {
        id: "msg_runtime_refresh_final",
        type: "message",
        role: "assistant",
        content: [],
        model: "runtime-new-model",
        stop_reason: null,
        stop_sequence: null,
      },
    }),
    runtimeRefreshAnthropicEvent("content_block_start", {
      index: 0,
      content_block: { type: "text", text: "" },
    }),
    runtimeRefreshAnthropicEvent("content_block_delta", {
      index: 0,
      delta: { type: "text_delta", text },
    }),
    runtimeRefreshAnthropicEvent("content_block_stop", { index: 0 }),
    runtimeRefreshAnthropicEvent("message_delta", {
      delta: { stop_reason: "end_turn", stop_sequence: null },
    }),
    runtimeRefreshAnthropicEvent("message_stop", {}),
  ].join("");
}

/** 自动标题仍走当前 Anthropic Provider；它不计入同 Turn 的三次 ASSISTANT Usage。 */
function runtimeRefreshAnthropicTitleStream(text) {
  return [
    runtimeRefreshAnthropicEvent("message_start", {
      message: {
        id: "msg_runtime_refresh_title",
        type: "message",
        role: "assistant",
        content: [],
        model: "runtime-new-model",
        stop_reason: null,
        stop_sequence: null,
        usage: { input_tokens: 5, output_tokens: 0 },
      },
    }),
    runtimeRefreshAnthropicEvent("content_block_start", {
      index: 0,
      content_block: { type: "text", text: "" },
    }),
    runtimeRefreshAnthropicEvent("content_block_delta", {
      index: 0,
      delta: { type: "text_delta", text },
    }),
    runtimeRefreshAnthropicEvent("content_block_stop", { index: 0 }),
    runtimeRefreshAnthropicEvent("message_delta", {
      delta: { stop_reason: "end_turn", stop_sequence: null },
      usage: { output_tokens: 4 },
    }),
    runtimeRefreshAnthropicEvent("message_stop", {}),
  ].join("");
}

/** 以精确 Content-Type 写入 Provider 流，并在 flush 后记录传输终态。 */
function writeRuntimeRefreshProviderStream(response, stream, attempt) {
  const body = Buffer.from(stream, "utf8");
  response.writeHead(200, {
    "content-type": "text/event-stream; charset=utf-8",
    "content-length": String(body.length),
    "cache-control": "no-store",
  });
  attempt.responded = true;
  response.end(body);
}

/**
 * 验证 Provider 只看见固定 MCP meta-tool 及其完整 action 合同，不把远端名称或动态 Schema 暴露为函数。
 */
function runtimeRefreshMetaToolContract(payload, api) {
  const tools = Array.isArray(payload?.tools) ? payload.tools : [];
  const matches = tools.filter((tool) => tool?.name === runtimeRefreshFixtureContract.metaToolName);
  const directRemoteToolExposed = tools.some(
    (tool) =>
      tool?.name === runtimeRefreshFixtureContract.toolName ||
      tool?.name ===
        `${runtimeRefreshFixtureContract.metaToolName}:${runtimeRefreshFixtureContract.serverId}:${runtimeRefreshFixtureContract.toolName}`,
  );
  const schema = api === "openai_responses" ? matches[0]?.parameters : matches[0]?.input_schema;
  const properties = schema?.properties;
  const propertyNames = properties === undefined ? [] : Object.keys(properties).sort();
  const required = Array.isArray(schema?.required) ? [...schema.required].sort() : [];
  const schemaTypes = (value) => {
    const types = new Set();
    const visit = (candidate, depth) => {
      if (depth > 4 || candidate === null || typeof candidate !== "object") return;
      if (typeof candidate.type === "string") types.add(candidate.type);
      if (Array.isArray(candidate.type)) {
        for (const type of candidate.type) if (typeof type === "string") types.add(type);
      }
      for (const key of ["anyOf", "oneOf"]) {
        if (Array.isArray(candidate[key])) {
          for (const alternative of candidate[key]) visit(alternative, depth + 1);
        }
      }
    };
    visit(value, 0);
    return types;
  };
  const hasTypes = (value, ...expected) => {
    const types = schemaTypes(value);
    return expected.every((type) => types.has(type));
  };
  const expectedProperties = ["action", "argumentsJson", "offset", "query", "serverId", "toolName"];
  const actionValues = properties?.action?.enum;
  const expectedActions = ["status", "search", "describe", "call"];
  return {
    valid:
      matches.length === 1 &&
      !directRemoteToolExposed &&
      schema?.type === "object" &&
      schema.additionalProperties === false &&
      JSON.stringify(propertyNames) === JSON.stringify(expectedProperties) &&
      JSON.stringify(required) === JSON.stringify(expectedProperties) &&
      JSON.stringify(actionValues) === JSON.stringify(expectedActions) &&
      hasTypes(properties.serverId, "string", "null") &&
      hasTypes(properties.toolName, "string", "null") &&
      hasTypes(properties.query, "string", "null") &&
      hasTypes(properties.argumentsJson, "string", "null") &&
      hasTypes(properties.offset, "integer", "null"),
    uniqueMetaTool: matches.length === 1,
    directRemoteToolExposed,
  };
}

/**
 * 启动双协议 loopback Provider。只保留请求 Profile 与按 call ID 解析的结果证据，不持久化 prompt、参数或 Header；
 * 首个请求门覆盖旧 Turn，ordinal 4/5 门分别固定新 admission 的 describe 与 call 响应边界，便于核实持久状态先后。
 */
async function startRuntimeRefreshProviderFixture() {
  const attempts = [];
  const firstRequestGate = createFixtureGate();
  const v2DescribeResponseGate = createFixtureGate();
  const v2CallResponseGate = createFixtureGate();
  let turnRequestCount = 0;
  const server = createHttpServer(async (request, response) => {
    if (request.method !== "POST") {
      response.writeHead(405, { "content-length": "0" });
      response.end();
      return;
    }
    let payload;
    try {
      payload = await readBoundedFixtureJson(request);
    } catch {
      response.writeHead(400, { "content-length": "0" });
      response.end();
      return;
    }
    const api = request.url?.endsWith("/responses")
      ? "openai_responses"
      : request.url?.endsWith("/messages")
        ? "anthropic_messages"
        : undefined;
    if (api === undefined) {
      response.writeHead(404, { "content-length": "0" });
      response.end();
      return;
    }
    const serialized = JSON.stringify(payload);
    const titleRequest =
      serialized.includes("<user_request>") && serialized.includes("<assistant_reply>");
    const attempt = {
      kind: titleRequest ? "title" : "turn",
      api,
      ordinal: titleRequest ? undefined : ++turnRequestCount,
      responded: false,
      finished: false,
      disconnected: false,
    };
    attempts.push(attempt);
    response.once("finish", () => {
      attempt.finished = true;
    });
    response.once("close", () => {
      if (!attempt.finished) attempt.disconnected = true;
    });
    if (titleRequest) {
      if (api !== "anthropic_messages") {
        response.writeHead(409, { "content-length": "0" });
        response.end();
        return;
      }
      writeRuntimeRefreshProviderStream(
        response,
        runtimeRefreshAnthropicTitleStream(runtimeRefreshFixtureContract.automaticTitle),
        attempt,
      );
      return;
    }
    const metaToolContract = runtimeRefreshMetaToolContract(payload, api);
    if (attempt.ordinal === 1) {
      Object.assign(attempt, {
        contractValid:
          api === "openai_responses" &&
          payload.model === "runtime-old-model" &&
          serialized.includes(runtimeRefreshFixtureContract.firstPrompt) &&
          serialized.includes(runtimeRefreshFixtureContract.oldWorkspaceMarker) &&
          serialized.includes(runtimeRefreshFixtureContract.oldSkillMarker) &&
          metaToolContract.valid,
        oldPromptSeen: serialized.includes(runtimeRefreshFixtureContract.oldWorkspaceMarker),
        oldSkillSeen: serialized.includes(runtimeRefreshFixtureContract.oldSkillMarker),
        v1DescribeRequested: true,
        metaToolSchemaValid: metaToolContract.valid,
        uniqueMetaTool: metaToolContract.uniqueMetaTool,
        directRemoteToolExposed: metaToolContract.directRemoteToolExposed,
      });
      if (!attempt.contractValid) {
        response.writeHead(409, { "content-length": "0" });
        response.end();
        return;
      }
      await firstRequestGate.promise;
      if (!attempt.disconnected && !response.destroyed) {
        writeRuntimeRefreshProviderStream(
          response,
          runtimeRefreshOpenAiToolStream("call_runtime_refresh_v1_describe", "describe"),
          attempt,
        );
      }
      return;
    }
    if (attempt.ordinal === 2) {
      const v1DescribeDiagnostics = runtimeRefreshDescribeResultDiagnostics(
        payload,
        "call_runtime_refresh_v1_describe",
        1,
      );
      const v1DescribeSeen = runtimeRefreshDescribeResultMatches(
        payload,
        api,
        "call_runtime_refresh_v1_describe",
        1,
      );
      Object.assign(attempt, {
        contractValid:
          api === "openai_responses" &&
          payload.model === "runtime-old-model" &&
          serialized.includes(runtimeRefreshFixtureContract.oldWorkspaceMarker) &&
          serialized.includes(runtimeRefreshFixtureContract.oldSkillMarker) &&
          v1DescribeSeen &&
          metaToolContract.valid,
        oldPromptSeen: serialized.includes(runtimeRefreshFixtureContract.oldWorkspaceMarker),
        oldSkillSeen: serialized.includes(runtimeRefreshFixtureContract.oldSkillMarker),
        v1DescribeSeen,
        v1DescribeDiagnostics,
        metaToolSchemaValid: metaToolContract.valid,
        uniqueMetaTool: metaToolContract.uniqueMetaTool,
        directRemoteToolExposed: metaToolContract.directRemoteToolExposed,
      });
      if (!attempt.contractValid) {
        response.writeHead(409, { "content-length": "0" });
        response.end();
        return;
      }
      writeRuntimeRefreshProviderStream(
        response,
        runtimeRefreshOpenAiToolStream(
          "call_runtime_refresh_v1_call",
          "call",
          JSON.stringify({ value: "old-value" }),
        ),
        attempt,
      );
      return;
    }
    if (attempt.ordinal === 3) {
      const oldCallResultItems = runtimeRefreshNativeToolResultItems(
        payload,
        api,
        "call_runtime_refresh_v1_call",
      );
      const oldCallResult = runtimeRefreshNativeToolResult(
        payload,
        api,
        "call_runtime_refresh_v1_call",
      );
      const oldCallOutput =
        oldCallResult === undefined
          ? undefined
          : runtimeRefreshParseAuditedText(oldCallResult.content);
      const oldCallResultSeen =
        oldCallOutput?.valid === true &&
        oldCallOutput.content ===
          "Tool failed with code MCP_TOOL_FAILED (category: tool_binding_unavailable)." &&
        oldCallOutput.error === "tool_error";
      const oldCallResultDiagnostics = {
        matchingOutputCount: oldCallResultItems.length,
        outputType: oldCallResult === undefined ? null : typeof oldCallResult.content,
        providerErrorFlag:
          typeof oldCallResult?.result?.is_error === "boolean"
            ? oldCallResult.result.is_error
            : null,
        outputAuditValid: oldCallOutput?.valid === true,
        outputAuditReason: oldCallOutput?.reason ?? null,
        codePointCountValid: oldCallOutput?.codePointCountValid ?? null,
        sha256Valid: oldCallOutput?.sha256Valid ?? null,
        expectedFailureBodyMatches:
          oldCallOutput?.valid === true &&
          oldCallOutput.content ===
            "Tool failed with code MCP_TOOL_FAILED (category: tool_binding_unavailable).",
        errorMetadata: oldCallOutput?.error ?? null,
        errorMetadataMatches: oldCallOutput?.error === "tool_error",
        exitCode: oldCallOutput?.exitCode ?? null,
      };
      Object.assign(attempt, {
        contractValid:
          api === "openai_responses" &&
          payload.model === "runtime-old-model" &&
          serialized.includes(runtimeRefreshFixtureContract.oldWorkspaceMarker) &&
          serialized.includes(runtimeRefreshFixtureContract.oldSkillMarker) &&
          oldCallResultSeen,
        oldCallResultSeen,
        oldCallResultDiagnostics,
      });
      if (!attempt.contractValid) {
        response.writeHead(409, { "content-length": "0" });
        response.end();
        return;
      }
      writeRuntimeRefreshProviderStream(
        response,
        runtimeRefreshOpenAiFinalStream(runtimeRefreshFixtureContract.firstFinalReply, 1),
        attempt,
      );
      return;
    }
    if (attempt.ordinal === 4) {
      Object.assign(attempt, {
        contractValid:
          api === "anthropic_messages" &&
          payload.model === "runtime-new-model" &&
          payload.output_config?.effort === "high" &&
          serialized.includes(runtimeRefreshFixtureContract.secondPrompt) &&
          serialized.includes(runtimeRefreshFixtureContract.newWorkspaceMarker) &&
          serialized.includes(runtimeRefreshFixtureContract.newSkillMarker) &&
          metaToolContract.valid,
        newPromptSeen: serialized.includes(runtimeRefreshFixtureContract.newWorkspaceMarker),
        newSkillSeen: serialized.includes(runtimeRefreshFixtureContract.newSkillMarker),
        metaToolSchemaValid: metaToolContract.valid,
        uniqueMetaTool: metaToolContract.uniqueMetaTool,
        directRemoteToolExposed: metaToolContract.directRemoteToolExposed,
      });
      if (!attempt.contractValid) {
        response.writeHead(409, { "content-length": "0" });
        response.end();
        return;
      }
      attempt.responseGateHeld = true;
      await v2DescribeResponseGate.promise;
      attempt.responseGateHeld = false;
      if (!attempt.disconnected && !response.destroyed) {
        writeRuntimeRefreshProviderStream(
          response,
          runtimeRefreshAnthropicDescribeStream(),
          attempt,
        );
      }
      return;
    }
    if (attempt.ordinal === 5) {
      const v2DescribeSeen = runtimeRefreshDescribeResultMatches(
        payload,
        api,
        "call_runtime_refresh_v2_describe",
        2,
      );
      Object.assign(attempt, {
        contractValid:
          api === "anthropic_messages" &&
          payload.model === "runtime-new-model" &&
          payload.output_config?.effort === "high" &&
          serialized.includes(runtimeRefreshFixtureContract.newWorkspaceMarker) &&
          serialized.includes(runtimeRefreshFixtureContract.newSkillMarker) &&
          v2DescribeSeen &&
          metaToolContract.valid,
        newPromptSeen: serialized.includes(runtimeRefreshFixtureContract.newWorkspaceMarker),
        newSkillSeen: serialized.includes(runtimeRefreshFixtureContract.newSkillMarker),
        v2DescribeSeen,
        metaToolSchemaValid: metaToolContract.valid,
        uniqueMetaTool: metaToolContract.uniqueMetaTool,
        directRemoteToolExposed: metaToolContract.directRemoteToolExposed,
      });
      if (!attempt.contractValid) {
        response.writeHead(409, { "content-length": "0" });
        response.end();
        return;
      }
      attempt.responseGateHeld = true;
      await v2CallResponseGate.promise;
      attempt.responseGateHeld = false;
      if (!attempt.disconnected && !response.destroyed) {
        writeRuntimeRefreshProviderStream(response, runtimeRefreshAnthropicToolStream(), attempt);
      }
      return;
    }
    if (attempt.ordinal === 6) {
      const v2CallResult = runtimeRefreshNativeToolResult(
        payload,
        api,
        "call_runtime_refresh_v2_call",
      );
      const v2CallOutput =
        v2CallResult === undefined
          ? undefined
          : runtimeRefreshParseAuditedText(v2CallResult.content);
      const privateContinuationSeen =
        serialized.includes(runtimeRefreshFixtureContract.thinking) &&
        serialized.includes(runtimeRefreshFixtureContract.signature) &&
        v2CallResult !== undefined &&
        v2CallResult.result.is_error === false &&
        v2CallOutput?.valid === true &&
        v2CallOutput.content.trim() !== "";
      Object.assign(attempt, {
        contractValid:
          api === "anthropic_messages" &&
          payload.model === "runtime-new-model" &&
          payload.output_config?.effort === "high" &&
          privateContinuationSeen,
        privateContinuationSeen,
        v2CallResultOutputAuditValid: v2CallOutput?.valid === true,
      });
      if (!attempt.contractValid) {
        response.writeHead(409, { "content-length": "0" });
        response.end();
        return;
      }
      writeRuntimeRefreshProviderStream(
        response,
        runtimeRefreshAnthropicFinalStream(runtimeRefreshFixtureContract.finalReply),
        attempt,
      );
      return;
    }
    response.writeHead(409, { "content-length": "0" });
    response.end();
  });
  await new Promise((resolvePromise, rejectPromise) => {
    server.once("error", rejectPromise);
    server.listen(0, "127.0.0.1", resolvePromise);
  });
  const address = server.address();
  if (address === null || typeof address === "string")
    throw new Error("Runtime Refresh Provider 未绑定端口");
  const baseUrl = `http://127.0.0.1:${address.port}/v1`;
  return {
    attempts,
    providerConfig: {
      apiKey: "DUMMY_RUNTIME_REFRESH",
      baseUrl,
      model: "runtime-old-model",
      name: "Runtime Refresh Provider",
      api: "openai_responses",
    },
    releaseFirstRequest: () => firstRequestGate.release(),
    releaseV2DescribeResponse: () => v2DescribeResponseGate.release(),
    releaseV2CallResponse: () => v2CallResponseGate.release(),
    close: async () => {
      firstRequestGate.release();
      v2DescribeResponseGate.release();
      v2CallResponseGate.release();
      server.closeAllConnections?.();
      await new Promise((resolvePromise) => server.close(resolvePromise));
    },
    diagnosticSnapshot: () => attempts.map((attempt) => ({ ...attempt })),
  };
}

/**
 * 首轮只返回一个真实 `read` Tool call；后续 Provider 请求必须等整批 Tool 持久化后才会出现，
 * 因而可用请求顺序证明 Steering 没有中断在途 Provider 或 Tool。
 */
function inputQueueToolStream(requestNumber, workspacePath) {
  const responseId = `resp_queue_tool_${requestNumber}`;
  const argumentsJson = JSON.stringify({
    path: join(workspacePath, "sample.ts"),
    offset: 1,
    limit: 8,
  });
  const item = {
    id: `item_queue_tool_${requestNumber}`,
    type: "function_call",
    call_id: `call_queue_tool_${requestNumber}`,
    name: "read",
    arguments: argumentsJson,
  };
  return [
    titleFixtureEvent("response.output_item.added", 0, {
      output_index: 0,
      item: { ...item, arguments: "" },
    }),
    titleFixtureEvent("response.function_call_arguments.done", 1, {
      item_id: item.id,
      arguments: item.arguments,
      output_index: 0,
    }),
    titleFixtureEvent("response.output_item.done", 2, { output_index: 0, item }),
    titleFixtureEvent("response.completed", 3, {
      response: titleFixtureResponse(responseId, "completed", [item], true),
    }),
  ].join("");
}

/**
 * 生成具有精确 UTF-8 字节数和逻辑行数的 ASCII fixture；首行保留短 marker，后续 edit
 * 只替换该 marker，从而每个 revision 都测同一大文件而不重复搬运正文。
 */
export function turnChangeReviewContent(byteLength, logicalLines, marker) {
  if (
    !Number.isSafeInteger(byteLength) ||
    !Number.isSafeInteger(logicalLines) ||
    logicalLines < 1 ||
    marker.length + Math.max(0, logicalLines - 1) > byteLength
  ) {
    throw new Error("Turn Change Review fixture 预算无效");
  }
  const lineBreaks = Math.max(0, logicalLines - 1);
  const suffixBytes = byteLength - marker.length - lineBreaks;
  return `${marker}${"\n".repeat(lineBreaks)}${"x".repeat(suffixBytes)}`;
}

/**
 * 每个 Provider continuation 只返回一个原生 write call，使 App Server 分别持久化 64 KiB 与
 * 1 MiB 冻结文件；后续 30 次查看都读取同一终态 artifact，不以重复 Tool commit 代替读取性能。
 */
export function turnChangeReviewToolStream(tool, argumentsValue, step) {
  if (!new Set(["small", "large"]).has(step)) {
    throw new Error(`Turn Change Review Tool 阶段无效：${String(step)}`);
  }
  const responseId = `resp_turn_change_review_${step}`;
  const item = {
    id: `item_turn_change_review_${step}`,
    type: "function_call",
    call_id: `call_turn_change_review_${step}`,
    name: tool,
    arguments: JSON.stringify(argumentsValue),
  };
  return [
    titleFixtureEvent("response.output_item.added", 0, {
      output_index: 0,
      item: { ...item, arguments: "" },
    }),
    titleFixtureEvent("response.function_call_arguments.done", 1, {
      item_id: item.id,
      arguments: item.arguments,
      output_index: 0,
    }),
    titleFixtureEvent("response.output_item.done", 2, { output_index: 0, item }),
    titleFixtureEvent("response.completed", 3, {
      response: titleFixtureResponse(responseId, "completed", [item], true),
    }),
  ].join("");
}

/**
 * 只认可当前 Review fixture 的固定 Tool identity；HTTP 重试不会推进阶段，失败 Tool 输出也不会
 * 被误当作已完成修改。闭集结果不保留 output 正文，诊断只暴露成功、失败与重复 identity。
 */
export function inspectTurnChangeReviewToolOutputs(input) {
  const expected = ["call_turn_change_review_small", "call_turn_change_review_large"];
  const matches = Array.isArray(input)
    ? input.filter(
        (item) => item?.type === "function_call_output" && expected.includes(item.call_id),
      )
    : [];
  const successfulCallIds = [];
  const failedCallIds = [];
  const duplicateCallIds = [];
  for (const callId of expected) {
    const outputs = matches.filter((item) => item.call_id === callId);
    if (outputs.length > 1) duplicateCallIds.push(callId);
    if (outputs.length === 1) {
      if (outputs[0].status === "incomplete") failedCallIds.push(callId);
      else successfulCallIds.push(callId);
    }
  }
  const contiguous = successfulCallIds.every((callId, index) => callId === expected[index]);
  return {
    successfulCallIds,
    failedCallIds,
    duplicateCallIds,
    successfulCount: contiguous ? successfulCallIds.length : 0,
    valid: contiguous && failedCallIds.length === 0 && duplicateCallIds.length === 0,
  };
}

/** 返回实际 SSE frame 的 UTF-8 字节数，生产 fixture 在发送前据此守住单事件 2 MiB 上限。 */
export function turnChangeReviewSseEventBytes(stream) {
  if (typeof stream !== "string" || stream.length === 0) {
    throw new Error("Turn Change Review SSE 不能为空");
  }
  return stream
    .split("\n\n")
    .filter((frame) => frame.length > 0)
    .map((frame) => Buffer.byteLength(`${frame}\n\n`, "utf8"));
}

/**
 * 等待 ServerResponse 的真实 drain 或关闭；关闭属于可重试的传输终态，不把正常 Provider 重试
 * 升级为 fixture handler 崩溃。
 */
function waitForTurnChangeReviewDrain(response) {
  return new Promise((resolveDrain, rejectDrain) => {
    const cleanup = () => {
      response.off("drain", onDrain);
      response.off("close", onClose);
      response.off("error", onError);
    };
    const onDrain = () => {
      cleanup();
      resolveDrain(true);
    };
    const onClose = () => {
      cleanup();
      resolveDrain(false);
    };
    const onError = (error) => {
      cleanup();
      rejectDrain(error);
    };
    response.once("drain", onDrain);
    response.once("close", onClose);
    response.once("error", onError);
  });
}

/**
 * Review 的大 Tool SSE 以 64 KiB 有界分块并尊重 backpressure；其它 fixture 继续使用 11 字节
 * 碎片以覆盖流解析边界，避免为修复压力夹具降低既有协议测试强度。
 */
export async function writeTurnChangeReviewFixtureBody(response, body) {
  const chunkBytes = 64 * 1024;
  let chunks = 0;
  let drainWaits = 0;
  let writtenBytes = 0;
  for (let offset = 0; offset < body.length; offset += chunkBytes) {
    if (response.destroyed || response.writableEnded) break;
    const chunk = body.subarray(offset, offset + chunkBytes);
    chunks += 1;
    writtenBytes += chunk.length;
    if (!response.write(chunk)) {
      drainWaits += 1;
      if (!(await waitForTurnChangeReviewDrain(response))) break;
    }
  }
  return { chunks, drainWaits, writtenBytes, disconnected: writtenBytes !== body.length };
}

/**
 * 返回两个真实 Shell 调用：首项快速完成，次项等待 stdin EOF 后短暂运行。
 * 两个调用使用全局唯一身份，使真窗能观察逐 ordinal 结算而不触发数据库主键冲突。
 */
function toolLifecycleStream(requestNumber) {
  const responseId = `resp_tool_lifecycle_${requestNumber}`;
  const definitions = [
    {
      id: `item_tool_lifecycle_fast_${requestNumber}`,
      call_id: `call_tool_lifecycle_fast_${requestNumber}`,
      command: "Write-Output 'JA_WEBVIEW_FIRST_TOOL'",
    },
    {
      id: `item_tool_lifecycle_eof_${requestNumber}`,
      call_id: `call_tool_lifecycle_eof_${requestNumber}`,
      command:
        "$input=[Console]::In.ReadToEnd(); if($input.Length -ne 0){exit 9}; " +
        "Start-Sleep -Seconds 3; Write-Output 'JA_WEBVIEW_STDIN_EOF'",
    },
  ];
  const items = definitions.map((definition) => ({
    id: definition.id,
    type: "function_call",
    call_id: definition.call_id,
    name: "exec_command",
    arguments: JSON.stringify({ cmd: definition.command }),
  }));
  const events = [];
  let sequence = 0;
  for (const [outputIndex, item] of items.entries()) {
    events.push(
      titleFixtureEvent("response.output_item.added", sequence++, {
        output_index: outputIndex,
        item: { ...item, arguments: "" },
      }),
      titleFixtureEvent("response.function_call_arguments.done", sequence++, {
        item_id: item.id,
        arguments: item.arguments,
        output_index: outputIndex,
      }),
      titleFixtureEvent("response.output_item.done", sequence++, {
        output_index: outputIndex,
        item,
      }),
    );
  }
  events.push(
    titleFixtureEvent("response.completed", sequence, {
      response: titleFixtureResponse(responseId, "completed", items, true),
    }),
  );
  return events.join("");
}

/**
 * 先返回模型可纠正的原生 Tool 错误，再返回一个真实成功调用；连续三个 Read schema 错误
 * 刻意超过旧熔断阈值，证明失败结果只反馈模型且不会移除 Tool catalog 或强制终止本轮。
 */
function toolFailureStream(scenario, scenarioTurnAttempt, requestNumber, workspacePath) {
  const readRecovery = scenario.id === "read_stall_failure";
  const readArgumentsInvalid = readRecovery && scenarioTurnAttempt <= 3;
  const recoveringUnknownTool = !readRecovery && scenarioTurnAttempt === 1;
  const responseId = `resp_${scenario.id}_${requestNumber}`;
  const item = {
    id: `item_${scenario.id}_${requestNumber}`,
    type: "function_call",
    call_id: `call_${scenario.id}_${requestNumber}`,
    name: recoveringUnknownTool ? "unknown_e2e_tool" : readRecovery ? "read" : "exec_command",
    arguments: JSON.stringify(
      readRecovery
        ? readArgumentsInvalid
          ? { path: join(workspacePath, businessFixtureFile), offset: "one", limit: 8 }
          : { path: join(workspacePath, businessFixtureFile), offset: 1, limit: 8 }
        : recoveringUnknownTool
          ? {}
          : { cmd: "Write-Output 'JA_E2E_UNKNOWN_TOOL_RECOVERED'" },
    ),
  };
  return [
    titleFixtureEvent("response.output_item.added", 0, {
      output_index: 0,
      item: { ...item, arguments: "" },
    }),
    titleFixtureEvent("response.function_call_arguments.done", 1, {
      item_id: item.id,
      arguments: item.arguments,
      output_index: 0,
    }),
    titleFixtureEvent("response.output_item.done", 2, { output_index: 0, item }),
    titleFixtureEvent("response.completed", 3, {
      response: titleFixtureResponse(responseId, "completed", [item], true),
    }),
  ].join("");
}

/**
 * 把 DSML-like 标记拆到多个原生文本 delta 中，同时让 completed item 保留完整正文；这证明
 * 流边界和标记内容都不会把普通助手文本误判成 Tool，也不会依赖 TCP 恰好如何分包。
 */
function ordinaryDsmlTextStream(text, requestNumber) {
  if (ordinaryDsmlTextFragments.join("") !== text) {
    throw new Error("DSML-like 普通文本 fixture 与分片合同不一致");
  }
  const responseId = `resp_model_protocol_text_${requestNumber}`;
  const itemId = `message_model_protocol_text_${requestNumber}`;
  const finalItem = {
    id: itemId,
    type: "message",
    role: "assistant",
    status: "completed",
    content: [{ type: "output_text", text, annotations: [], logprobs: [] }],
  };
  const events = [
    titleFixtureEvent("response.created", 0, {
      response: titleFixtureResponse(responseId, "in_progress", [], false),
    }),
  ];
  for (const [index, fragment] of ordinaryDsmlTextFragments.entries()) {
    events.push(
      titleFixtureEvent("response.output_text.delta", index + 1, {
        content_index: 0,
        delta: fragment,
        item_id: itemId,
        logprobs: [],
        output_index: 0,
      }),
    );
  }
  const completedSequence = ordinaryDsmlTextFragments.length + 1;
  events.push(
    titleFixtureEvent("response.output_text.done", completedSequence, {
      content_index: 0,
      item_id: itemId,
      output_index: 0,
      text,
    }),
    titleFixtureEvent("response.completed", completedSequence + 1, {
      response: titleFixtureResponse(responseId, "completed", [finalItem], true),
    }),
  );
  return events.join("");
}

