/**
 * 固定重启恢复必须显式点击身份匹配的历史行；列表聚合结果不能冒充当前选中 Thread，
 * 也不能通过创建新会话或绕过 UI 的原生 RPC 满足持久身份断言。
 * @author kongweiguang
 */
export function assertTaskThreadsRestartSelectionContract() {
  const restartSource = String(runTaskThreadsRestartSession);
  const selectorSource = String(selectThreadById);
  const requiredOrder = [
    "await waitForRuntimeReady(page, deadline, signal);",
    "await waitForInitialThread(page, deadline, signal);",
    "await selectThreadById(page, expectation.rootThreadId, deadline, signal);",
    "if ((await currentThreadId(page, deadline, signal)) !== expectation.rootThreadId)",
  ];
  let previousIndex = -1;
  const ordered = requiredOrder.every((source) => {
    const currentIndex = restartSource.indexOf(source);
    if (currentIndex <= previousIndex) return false;
    previousIndex = currentIndex;
    return true;
  });
  const checks = {
    waitThenSelectThenVerify: ordered,
    identityBoundVisibleHistoryClick:
      selectorSource.includes('button[data-thread-id="${threadId}"]') &&
      selectorSource.includes('await target.waitFor({ state: "visible"') &&
      selectorSource.includes("await target.click({ timeout: timeout() });") &&
      selectorSource.includes('selected?.getAttribute("data-thread-id") === expected'),
    noFirstRowSelectionShortcut: !restartSource.includes(".first().click()"),
    noNewThreadCreation:
      !restartSource.includes("createInitialConversationThread") &&
      !restartSource.includes("ja_thread_create") &&
      !selectorSource.includes("ja_thread_create"),
    noRawRpcShortcut:
      !restartSource.includes("__TAURI_INTERNALS__") &&
      !selectorSource.includes("__TAURI_INTERNALS__") &&
      !restartSource.includes('invoke("ja_thread_read"') &&
      !selectorSource.includes('invoke("ja_thread_read"'),
  };
  const failedChecks = Object.entries(checks)
    .filter(([, passed]) => !passed)
    .map(([name]) => name);
  if (failedChecks.length > 0) {
    throw new Error(`Task 重启主 Thread 选择契约漂移：${failedChecks.join(", ")}`);
  }
}

